                                    {isCorrect && <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>}
                                </div>
                                <span className="flex-1">{renderText(opt)}</span>
                            </div>
                        )
                    })}
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { QUESTIONS_SPS, QUESTIONS_STT } from './constants';
import { AppMode, TestResult, Question, Subject } from './types';
import { TestRunner } from './components/TestRunner';
import { BrowserQuestionItem } from './components/BrowserQuestionItem';
import { LoginScreen } from './components/LoginScreen';
import { Leaderboard } from './components/Leaderboard';
import { SPSInfoModal } from './components/SPSInfoModal';
import { ReportModal } from './components/ReportModal';
import { AppUser } from './users';
import { db, auth } from './firebaseConfig';
import { doc, getDoc, setDoc, onSnapshot } from 'firebase/firestore';
import { onAuthStateChanged, signOut } from 'firebase/auth';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<AppUser | null>(null);
  const [loadingUser, setLoadingUser] = useState(true);

  const [subject, setSubject] = useState<Subject | null>(null);
  const [mode, setMode] = useState<AppMode>(AppMode.MENU);

  const [showSPSPopup, setShowSPSPopup] = useState(false);
  const [reportingQuestionId, setReportingQuestionId] = useState<number | null>(null);

  const [returnToMainMenu, setReturnToMainMenu] = useState(false);

  const [mistakesSPS, setMistakesSPS] = useState<number[]>([]);
  const [mistakesSTT, setMistakesSTT] = useState<number[]>([]);

  const [lastResult, setLastResult] = useState<TestResult | null>(null);
  const [browserSearch, setBrowserSearch] = useState("");

  const [expandedIds, setExpandedIds] = useState<Set<number>>(new Set());

  const [lastTestQuestions, setLastTestQuestions] = useState<Question[]>([]);
  const [lastUserAnswers, setLastUserAnswers] = useState<Record<number, number>>({});

  useEffect(() => {
      if(!auth) { setLoadingUser(false); return; }
      const unsubscribe = onAuthStateChanged(auth, (user) => {
          if (user) {
              setCurrentUser({ uid: user.uid, email: user.email || '', displayName: user.displayName || 'Student' });
          } else { setCurrentUser(null); }
          setLoadingUser(false);
      });
      return () => unsubscribe();
  }, []);

  const handleLogout = () => {
      localStorage.removeItem('app_session_id');
      if(auth) signOut(auth);
      setSubject(null);
      setMode(AppMode.MENU);
      setLastResult(null);
      setExpandedIds(new Set());
  };

  useEffect(() => {
    if (currentUser && db) {
        const userDocRef = doc(db, "users", currentUser.uid);
        let localSessionId = localStorage.getItem('app_session_id');
        if (!localSessionId) {
             localSessionId = Date.now().toString() + "-" + Math.random().toString(36).substr(2, 9);
             localStorage.setItem('app_session_id', localSessionId);
             setDoc(userDocRef, { sessionId: localSessionId }, { merge: true });
        }
        const unsubDoc = onSnapshot(userDocRef, (docSnap) => {
            if (docSnap.exists()) {
                const data = docSnap.data();
                setMistakesSPS(data.mistakesSPS || []);
                setMistakesSTT(data.mistakesSTT || []);
                if (currentUser.displayName && data.displayName !== currentUser.displayName) {
                    setDoc(userDocRef, { displayName: currentUser.displayName }, { merge: true });
                }
                if (data.sessionId && data.sessionId !== localSessionId) {
                    alert("Byli jste odhlášeni z jiného zařízení.");
                    handleLogout();
                }
            } else {
                setDoc(userDocRef, { mistakesSPS: [], mistakesSTT: [], lastLogin: new Date().toISOString(), displayName: currentUser.displayName, sessionId: localSessionId }, { merge: true });
            }
        });
        return () => unsubDoc();
    }
  }, [currentUser]);

  const currentQuestions = useMemo(() => {
    if (subject === 'SPS') return QUESTIONS_SPS;
    if (subject === 'STT') return QUESTIONS_STT;
    return [];
  }, [subject]);

  const currentMistakes = subject === 'SPS' ? mistakesSPS : mistakesSTT;

  const setMistakes = async (newMistakes: number[]) => {
      if (subject === 'SPS') setMistakesSPS(newMistakes);
      else if (subject === 'STT') setMistakesSTT(newMistakes);
      if (currentUser && db) {
          try {
              const userDocRef = doc(db, "users", currentUser.uid);
              await setDoc(userDocRef, subject === 'SPS' ? { mistakesSPS: newMistakes } : { mistakesSTT: newMistakes }, { merge: true });
          } catch (e) { console.error("Chyba:", e); }
      }
  };

  const handleSPSSelection = () => {
    if (localStorage.getItem('hideSPSInfo')) {
      setSubject('SPS');
      setBrowserSearch("");
    } else { setShowSPSPopup(true); }
  };

  const handleTestComplete = (result: TestResult) => {
    setLastResult(result);
    if (mode === AppMode.MOCK_TEST) {
        setMistakes(Array.from(new Set([...currentMistakes, ...result.mistakes])));
        setLastTestQuestions(result.questionsUsed);
        setLastUserAnswers(result.userAnswers);
    } else if (mode === AppMode.MISTAKES) { setMistakes(result.mistakes); }
    setMode(AppMode.MENU);
  };

  const closeBrowser = () => { setMode(AppMode.MENU); setBrowserSearch(""); setExpandedIds(new Set()); };

  const toggleQuestion = (id: number) => {
      const newSet = new Set(expandedIds);
      if (newSet.has(id)) newSet.delete(id); else newSet.add(id);
      setExpandedIds(newSet);
  };

  const renderBrowser = () => {
      const filtered = currentQuestions.filter(q => q.text.toLowerCase().includes(browserSearch.toLowerCase()) || q.id.toString().includes(browserSearch));
      const areAllExpanded = filtered.length > 0 && filtered.every(q => expandedIds.has(q.id));
      const handleToggleAll = () => {
          if (areAllExpanded) setExpandedIds(new Set());
          else { const newSet = new Set(expandedIds); filtered.forEach(q => newSet.add(q.id)); setExpandedIds(newSet); }
      };
      return (
          <div className="max-w-4xl mx-auto w-full p-4">
               <div className="bg-white sticky top-0 z-10 shadow-sm border-b border-gray-200 px-6 py-4 mb-6 flex flex-col md:flex-row justify-between items-center rounded-b-xl gap-4">
                  <div className="flex items-center w-full md:w-auto gap-2">
                    <button onClick={closeBrowser} className="text-gray-500 hover:text-gray-900 p-2"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg></button>
                  </div>
                  <div className="flex-1 w-full relative flex gap-2">
                      <div className="relative flex-1">
                        <input type="text" value={browserSearch} onChange={(e) => setBrowserSearch(e.target.value)} placeholder="Hledat otázku..." className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg outline-none" />
                        <svg className="w-5 h-5 text-gray-400 absolute left-3 top-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                      </div>
                      <button onClick={handleToggleAll} className="px-4 py-2 rounded-lg font-medium text-sm bg-blue-50 text-blue-700 border border-blue-200 whitespace-nowrap">{areAllExpanded ? 'Sbalit vše' : 'Rozbalit vše'}</button>
                  </div>
              </div>
              <div className="space-y-4">
                  {filtered.length === 0 ? <div className="text-center py-12 text-gray-500">Nebyly nalezeny žádné otázky.</div> : 
                    filtered.map(q => <BrowserQuestionItem key={q.id} question={q} isExpanded={expandedIds.has(q.id)} onToggle={() => toggleQuestion(q.id)} onReportRequest={(id) => setReportingQuestionId(id)} />)
                  }
              </div>
          </div>
      );
  };

  if (loadingUser) return <div className="min-h-screen flex items-center justify-center text-gray-500">Načítám...</div>;
  if (!currentUser) return <LoginScreen onLogin={(user) => setCurrentUser(user)} />;

  return (
    <div className="min-h-screen bg-slate-50 text-gray-900 font-sans relative">
      {reportingQuestionId !== null && subject && (
        <ReportModal 
          questionId={reportingQuestionId} 
          subject={subject} 
          userName={currentUser.displayName} 
          onClose={() => setReportingQuestionId(null)} 
        />
      )}

      {showSPSPopup && <SPSInfoModal onConfirm={() => { setShowSPSPopup(false); setSubject('SPS'); setBrowserSearch(""); }} />}

      {lastResult && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-2xl p-8 max-w-md w-full shadow-2xl">
                <div className="text-center">
                    <div className={`mx-auto w-20 h-20 rounded-full flex items-center justify-center mb-4 ${lastResult.passed ? 'bg-green-100 text-green-600' : 'bg-red-100 text-red-600'}`}>
                        {lastResult.passed ? <svg className="w-10 h-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg> : <svg className="w-10 h-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>}
                    </div>
                    <h2 className="text-2xl font-bold text-gray-900 mb-1">{lastResult.passed ? "Prošel(a) jsi!" : "Neprošel(a) jsi"}</h2>
                    <p className="text-gray-500 mb-6">Skóre: <span className="font-bold text-gray-800">{Math.round((lastResult.score / lastResult.total) * 100)}%</span> ({lastResult.score}/{lastResult.total})</p>
                    <div className="grid grid-cols-2 gap-4 mb-6">
                        <div className="bg-gray-50 p-3 rounded-lg"><div className="text-xs text-gray-500">Chyby</div><div className="text-xl font-bold text-red-500">{lastResult.mistakes.length}</div></div>
                        <div className="bg-gray-50 p-3 rounded-lg"><div className="text-xs text-gray-500">Čas</div><div className="text-xl font-bold text-blue-600">{Math.floor(lastResult.timeElapsed / 60)}m</div></div>
                    </div>
                    <div className="space-y-3">
                        {lastTestQuestions.length > 0 && <button onClick={() => { setLastResult(null); setMode(AppMode.REVIEW); }} className="w-full py-3 rounded-lg border-2 border-gray-200 text-gray-700 font-bold hover:bg-gray-50">Prohlédnout odpovědi</button>}
                        <button onClick={() => setLastResult(null)} className="w-full py-3 rounded-lg bg-gray-900 text-white font-bold hover:bg-gray-800">Zavřít</button>
                    </div>
                </div>
            </div>
        </div>
      )}

      {!subject && (
      <div className="max-w-6xl mx-auto min-h-screen flex flex-col p-6">
          <div className="flex justify-end items-center gap-4 mb-12">
              <span className="text-gray-600 font-medium bg-white px-4 py-2 rounded-full shadow-sm border border-gray-100">👤 {currentUser.displayName}</span>
              <button onClick={handleLogout} className="text-sm text-red-500 hover:text-red-700 font-semibold border border-red-200 px-4 py-2 rounded-full">Odhlásit</button>
          </div>
          <div className="text-center mb-12"><h1 className="text-5xl font-bold text-gray-900 mb-4 tracking-tight">Maturitní testy</h1></div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 w-full max-w-4xl mx-auto mb-16">
              <button onClick={handleSPSSelection} className="group relative bg-white p-8 rounded-2xl shadow-lg border border-gray-100 transition-all text-center"><div className="absolute top-0 left-0 w-full h-1.5 bg-blue-500"></div><h2 className="text-3xl font-bold text-gray-800 mb-2">SPS</h2><p className="text-gray-500">Stavba a provoz strojů</p></button>
              <button onClick={() => { setSubject('STT'); setBrowserSearch(""); }} className="group relative bg-white p-8 rounded-2xl shadow-lg border border-gray-100 transition-all text-center"><div className="absolute top-0 left-0 w-full h-1.5 bg-orange-500"></div><h2 className="text-3xl font-bold text-gray-800 mb-2">STT</h2><p className="text-gray-500">Strojírenská technologie</p></button>
          </div>
          <div className="w-full max-w-5xl mx-auto"><h3 className="text-xl font-bold text-gray-400 uppercase text-center mb-6">Statistiky</h3><div className="grid grid-cols-1 md:grid-cols-2 gap-6"><div onClick={() => { setSubject('SPS'); setMode(AppMode.LEADERBOARD); setReturnToMainMenu(true); }} className="cursor-pointer transition-transform hover:-translate-y-1"><Leaderboard subject="SPS" variant="compact" /></div><div onClick={() => { setSubject('STT'); setMode(AppMode.LEADERBOARD); setReturnToMainMenu(true); }} className="cursor-pointer transition-transform hover:-translate-y-1"><Leaderboard subject="STT" variant="compact" /></div></div></div>
      </div>
      )}

      {subject && mode === AppMode.LEADERBOARD && <Leaderboard subject={subject} onBack={() => { if (returnToMainMenu) { setSubject(null); setReturnToMainMenu(false); } setMode(AppMode.MENU); }} variant="full" />}

      {subject && mode === AppMode.MENU && (
        <div className="max-w-6xl mx-auto min-h-screen flex flex-col p-4 md:p-8">
            <div className="flex flex-col md:flex-row justify-between items-center mb-8 gap-4">
                <div onClick={() => { setSubject(null); setBrowserSearch(""); }} className="cursor-pointer inline-flex items-center gap-2 px-5 py-2 rounded-full bg-white border border-gray-200 text-gray-600 font-medium text-sm shadow-sm hover:text-blue-600 transition-all">Zpět na výběr předmětu</div>
                <div className="text-right"><h1 className={`text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r ${subject === 'SPS' ? 'from-blue-700 to-indigo-600' : 'from-orange-600 to-red-600'}`}>Maturitní test {subject}</h1></div>
            </div>
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                <div className="lg:col-span-2 space-y-4">
                    <button onClick={() => setMode(AppMode.MOCK_TEST)} className="w-full p-6 bg-white rounded-xl shadow-md flex items-center gap-4 text-left border border-gray-100 hover:bg-blue-50">
                        <div className="bg-blue-100 p-3 rounded-full text-blue-700"><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg></div>
                        <div><div className="font-bold text-lg">Test nanečisto</div><div className="text-sm text-gray-500 font-normal">40 otázek • 30 minut</div></div>
                    </button>
                    <button onClick={() => setMode(AppMode.TRAINING)} className="w-full p-6 bg-white rounded-xl shadow-md flex items-center gap-4 text-left border border-gray-100 hover:bg-green-50">
                        <div className="bg-green-100 p-3 rounded-full text-green-700"><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg></div>
                        <div><div className="font-bold text-lg">Náhodný trénink</div><div className="text-sm text-gray-500 font-normal">Okamžitá kontrola</div></div>
                    </button>
                    <button onClick={() => setMode(AppMode.MISTAKES)} disabled={currentMistakes.length === 0} className="w-full p-6 bg-white rounded-xl shadow-md flex items-center gap-4 text-left border border-gray-100 hover:bg-orange-50 disabled:opacity-50">
                        <div className="bg-orange-100 p-3 rounded-full text-orange-700"><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg></div>
                        <div><div className="font-bold text-lg">Oprava chyb</div><div className="text-sm font-normal">{currentMistakes.length} chyb v paměti</div></div>
                    </button>
                    <button onClick={() => setMode(AppMode.BROWSER)} className="w-full p-6 bg-white rounded-xl shadow-md flex items-center gap-4 text-left border border-gray-100 hover:bg-indigo-50">
                        <div className="bg-indigo-100 p-3 rounded-full text-indigo-700"><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg></div>
                        <div><div className="font-bold text-lg">Prohlížet otázky</div><div className="text-sm text-gray-500 font-normal">Databáze {currentQuestions.length} otázek</div></div>
                    </button>
                </div>
                <div className="hidden lg:block lg:col-span-1"><div className="sticky top-8"><Leaderboard subject={subject} variant="compact" onBack={() => { setMode(AppMode.LEADERBOARD); setReturnToMainMenu(false); }} /></div></div>
            </div>
        </div>
      )}

      {subject && (mode === AppMode.MOCK_TEST || mode === AppMode.TRAINING || mode === AppMode.MISTAKES || mode === AppMode.REVIEW) && (
          <TestRunner key={subject + mode} mode={mode} mistakeIds={mode === AppMode.MISTAKES ? currentMistakes : undefined} onComplete={handleTestComplete} onExit={() => setMode(AppMode.MENU)} onReportRequest={(id) => setReportingQuestionId(id)} initialQuestionsForMode={currentQuestions} initialQuestions={mode === AppMode.REVIEW ? lastTestQuestions : undefined} initialAnswers={mode === AppMode.REVIEW ? lastUserAnswers : undefined} subject={subject} />
      )}

      {subject && mode === AppMode.BROWSER && renderBrowser()}
    </div>
  );
};

export default App;

