                  <h2 className="text-3xl font-bold text-gray-800 mb-2">STT</h2>
                  <p className="text-gray-500">Strojírenská technologie</p>
                  <p className="text-red-500 font-bold mt-4">Není hotové</p>
              </button>
          </div>
      </div>
