import React, { useState, useEffect } from 'react';
import { db } from '../firebaseConfig';
import { doc, setDoc, getDoc, collection, query, where, getDocs, updateDoc, serverTimestamp, deleteDoc } from 'firebase/firestore';
import { Subject, BattleRoom, AppMode } from '../types';
import { AppUser } from '../users';
import { BattleArena } from './BattleArena';
import { QUESTIONS_SPS } from '../constants';

interface Props {
  currentUser: AppUser;
  subject: Subject;
  stats: any;
  onExit: () => void;
}

export const BattleManager: React.FC<Props> = ({ currentUser, subject, stats, onExit }) => {
  const [view, setView] = useState<'JOIN' | 'LOBBY' | 'ARENA'>('JOIN');
  const [roomCode, setRoomCode] = useState('');
  const [currentRoom, setCurrentRoom] = useState<BattleRoom | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  // Kontrola denního limitu (2 bitvy)
  const canPlay = () => {
    const today = new Date().toISOString().split('T')[0];
    if (stats?.lastBattleDate === today && (stats?.battlesPlayedToday || 0) >= 2) {
      return false;
    }
    return true;
  };

  const createRoom = async () => {
    if (!canPlay()) {
      setError("Dnes jsi už vyčerpal limit 2 bitev. Zkus to zase zítra!");
      return;
    }

    setLoading(true);
    const code = Math.floor(100000 + Math.random() * 900000).toString();
    const roomId = `room_${Date.now()}`;

    // Vybrat náhodných 20 otázek pro battle
    const shuffled = [...QUESTIONS_SPS].sort(() => 0.5 - Math.random()).slice(0, 20);
    const questionIds = shuffled.map(q => q.id);

    const newRoom: BattleRoom = {
      id: roomId,
      code,
      subject,
      status: 'WAITING',
      questions: questionIds,
      players: {
        [currentUser.uid]: {
          uid: currentUser.uid,
          displayName: currentUser.displayName,
          progress: 0,
          score: 0,
          finished: false,
          ready: true
        }
      },
      createdAt: serverTimestamp()
    };

    await setDoc(doc(db, "battles", roomId), newRoom);
    setCurrentRoom(newRoom);
    setView('LOBBY');
    setLoading(false);
  };

  const joinRoom = async () => {
    if (!roomCode || roomCode.length !== 6) {
        setError("Zadej platný 6místný kód.");
        return;
    }

    if (!canPlay()) {
      setError("Dnes jsi už vyčerpal limit 2 bitev.");
      return;
    }

    setLoading(true);
    setError('');

    const q = query(collection(db, "battles"), where("code", "==", roomCode), where("status", "==", "WAITING"));
    const querySnapshot = await getDocs(q);

    if (querySnapshot.empty) {
      setError("Místnost nebyla nalezena nebo je už plná.");
      setLoading(false);
      return;
    }

    const roomDoc = querySnapshot.docs[0];
    const roomData = roomDoc.data() as BattleRoom;

    if (Object.keys(roomData.players).length >= 2) {
        setError("Místnost je plná.");
        setLoading(false);
        return;
    }

    const updatedPlayers = {
      ...roomData.players,
      [currentUser.uid]: {
        uid: currentUser.uid,
        displayName: currentUser.displayName,
        progress: 0,
        score: 0,
        finished: false,
        ready: true
      }
    };

    await updateDoc(doc(db, "battles", roomDoc.id), {
      players: updatedPlayers,
      status: 'STARTING'
    });

    setCurrentRoom({ ...roomData, players: updatedPlayers, status: 'STARTING' });
    setView('ARENA');
    setLoading(false);
  };

  if (view === 'ARENA' && currentRoom) {
      return <BattleArena room={currentRoom} currentUser={currentUser} onExit={onExit} stats={stats} />;
  }

  return (
    <div className="max-w-md mx-auto mt-20 p-6 bg-white rounded-2xl shadow-xl border border-gray-100">
      <h2 className="text-2xl font-bold text-center mb-6">1v1 Souboj (SPS)</h2>

      {error && (
        <div className="mb-4 p-3 bg-red-50 text-red-600 rounded-lg text-sm font-medium border border-red-100">
          {error}
        </div>
      )}

      {view === 'JOIN' ? (
        <div className="space-y-6">
          <button 
            onClick={createRoom}
            disabled={loading}
            className="w-full py-4 bg-blue-600 text-white font-bold rounded-xl shadow-lg hover:bg-blue-700 transition-all flex items-center justify-center gap-2"
          >
            {loading ? "Vytvářím..." : "Vytvořit novou hru"}
          </button>

          <div className="relative flex items-center py-2">
            <div className="flex-grow border-t border-gray-200"></div>
            <span className="flex-shrink mx-4 text-gray-400 text-sm">nebo se připoj</span>
            <div className="flex-grow border-t border-gray-200"></div>
          </div>

          <div className="space-y-3">
            <input 
              type="text" 
              value={roomCode}
              onChange={(e) => setRoomCode(e.target.value.replace(/\D/g,'').slice(0,6))}
              placeholder="Zadej kód od soupeře"
              className="w-full p-4 border border-gray-300 rounded-xl text-center text-2xl tracking-widest focus:ring-2 focus:ring-blue-500 outline-none"
            />
            <button 
              onClick={joinRoom}
              disabled={loading || roomCode.length !== 6}
              className="w-full py-4 bg-gray-900 text-white font-bold rounded-xl hover:bg-gray-800 disabled:opacity-50 transition-all"
            >
              Připojit se ke hře
            </button>
          </div>

          <button onClick={onExit} className="w-full py-2 text-gray-400 text-sm hover:text-gray-600 transition-colors">
            Zpět do menu
          </button>
        </div>
      ) : (
        <div className="text-center space-y-6">
          <div className="p-6 bg-blue-50 rounded-2xl border-2 border-dashed border-blue-200">
            <p className="text-blue-600 font-medium mb-2">Tvůj kód místnosti:</p>
            <h3 className="text-5xl font-black tracking-widest text-blue-900">{currentRoom?.code}</h3>
          </div>
          <p className="text-gray-500 animate-pulse">Čekáme, až se soupeř připojí...</p>
          <button 
            onClick={async () => {
                if (currentRoom) await deleteDoc(doc(db, "battles", currentRoom.id));
                setView('JOIN');
            }} 
            className="text-red-500 font-semibold text-sm"
          >
            Zrušit místnost
          </button>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { db } from '../firebaseConfig';
import { doc, onSnapshot, updateDoc, setDoc } from 'firebase/firestore';
import { BattleRoom, Question, Subject } from '../types';
import { AppUser } from '../users';
import { QUESTIONS_SPS } from '../constants';
import { QuestionCard } from './QuestionCard';

interface Props {
  room: BattleRoom;
  currentUser: AppUser;
  onExit: () => void;
  stats: any;
}

export const BattleArena: React.FC<Props> = ({ room, currentUser, onExit, stats }) => {
  const [battleData, setBattleData] = useState<BattleRoom>(room);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [currentQuestions, setCurrentQuestions] = useState<Question[]>([]);
  const [finished, setFinished] = useState(false);
  const [myScore, setMyScore] = useState(0);

  // Načtení otázek podle ID z místnosti
  useEffect(() => {
    const qs = room.questions.map(id => QUESTIONS_SPS.find(q => q.id === id)!).filter(Boolean);
    setCurrentQuestions(qs);

    // Započítat bitvu do limitu hned po startu
    const incrementBattleLimit = async () => {
        const userRef = doc(db, "users", currentUser.uid);
        const today = new Date().toISOString().split('T')[0];
        const newCount = stats?.lastBattleDate === today ? (stats?.battlesPlayedToday || 0) + 1 : 1;
        await updateDoc(userRef, {
            "statsSPS.battlesPlayedToday": newCount,
            "statsSPS.lastBattleDate": today
        });
    };
    incrementBattleLimit();
  }, []);

  // Sledování změn v bitvě
  useEffect(() => {
    const unsub = onSnapshot(doc(db, "battles", room.id), (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data() as BattleRoom;
        setBattleData(data);

        // Pokud jsou oba hotovi, ukážeme výsledek
        const players = Object.values(data.players);
        if (players.length === 2 && players.every(p => p.finished)) {
            setFinished(true);
        }
      }
    });
    return () => unsub();
  }, [room.id]);

  const handleAnswer = async (qId: number, idx: number, isCorrect: boolean) => {
    const newScore = isCorrect ? myScore + 1 : myScore;
    setMyScore(newScore);

    const isLast = currentIndex === currentQuestions.length - 1;
    const newProgress = currentIndex + 1;

    // Aktualizace postupu v DB
    await updateDoc(doc(db, "battles", room.id), {
      [`players.${currentUser.uid}.progress`]: newProgress,
      [`players.${currentUser.uid}.score`]: newScore,
      [`players.${currentUser.uid}.finished`]: isLast
    });

    if (!isLast) {
      setCurrentIndex(prev => prev + 1);
    }
  };

  const opponent = Object.values(battleData.players).find(p => p.uid !== currentUser.uid);
  const me = battleData.players[currentUser.uid];

  if (finished) {
    const winner = me.score > (opponent?.score || 0) ? 'win' : me.score < (opponent?.score || 0) ? 'loss' : 'draw';
    return (
        <div className="max-w-xl mx-auto mt-20 text-center p-8 bg-white rounded-3xl shadow-2xl border border-gray-100 animate-in zoom-in duration-300">
            <div className={`w-24 h-24 mx-auto mb-6 rounded-full flex items-center justify-center text-4xl ${winner === 'win' ? 'bg-yellow-100' : winner === 'loss' ? 'bg-red-100' : 'bg-gray-100'}`}>
                {winner === 'win' ? '🏆' : winner === 'loss' ? '💀' : '🤝'}
            </div>
            <h2 className="text-4xl font-black mb-2">
                {winner === 'win' ? 'Vítězství!' : winner === 'loss' ? 'Prohra' : 'Remíza'}
            </h2>
            <p className="text-gray-500 mb-8">Souboj SPS ukončen</p>

            <div className="grid grid-cols-2 gap-4 mb-8">
                <div className="p-4 bg-blue-50 rounded-2xl">
                    <p className="text-xs text-blue-600 uppercase font-bold mb-1">Ty</p>
                    <p className="text-3xl font-black text-blue-900">{me.score}</p>
                </div>
                <div className="p-4 bg-red-50 rounded-2xl">
                    <p className="text-xs text-red-600 uppercase font-bold mb-1">{opponent?.displayName || 'Soupeř'}</p>
                    <p className="text-3xl font-black text-red-900">{opponent?.score || 0}</p>
                </div>
            </div>

            <button onClick={onExit} className="w-full py-4 bg-gray-900 text-white font-bold rounded-2xl hover:bg-black transition-all">
                Zpět do menu
            </button>
        </div>
    );
  }

  const currentQ = currentQuestions[currentIndex];

  return (
    <div className="max-w-4xl mx-auto w-full px-4 pt-6">
      {/* Real-time Progress bars */}
      <div className="bg-white rounded-2xl shadow-md p-4 mb-8 sticky top-4 z-20 border border-gray-100">
        <div className="space-y-4">
            {/* Moje lajna */}
            <div>
                <div className="flex justify-between text-xs font-bold mb-1">
                    <span className="text-blue-600">TY ({me.score} b.)</span>
                    <span>{currentIndex}/{currentQuestions.length}</span>
                </div>
                <div className="w-full h-3 bg-gray-100 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 transition-all duration-500" style={{width: `${(currentIndex / currentQuestions.length) * 100}%`}}></div>
                </div>
            </div>
            {/* Soupeřova lajna */}
            <div>
                <div className="flex justify-between text-xs font-bold mb-1">
                    <span className="text-red-600">{opponent?.displayName?.toUpperCase() || 'SOUPEŘ'} ({(opponent?.score || 0)} b.)</span>
                    <span>{opponent?.progress || 0}/{currentQuestions.length}</span>
                </div>
                <div className="w-full h-3 bg-gray-100 rounded-full overflow-hidden">
                    <div className="h-full bg-red-500 transition-all duration-500" style={{width: `${((opponent?.progress || 0) / currentQuestions.length) * 100}%`}}></div>
                </div>
            </div>
        </div>
      </div>

      {currentQ && !me.finished ? (
          <QuestionCard 
            question={currentQ}
            mode={'TRAINING' as any}
            onAnswer={handleAnswer}
            showFeedback={true}
          />
      ) : (
          <div className="text-center p-12 bg-white rounded-2xl shadow-sm border border-gray-100">
              <div className="animate-bounce text-4xl mb-4">🏁</div>
              <h3 className="text-xl font-bold">Máš hotovo!</h3>
              <p className="text-gray-500">Čekáme, až soupeř dokončí test...</p>
          </div>
      )}
    </div>
  );
};

