                        <div><div className="font-bold text-lg">Oprava chyb</div><div className="text-sm font-normal">{currentMistakes.length} chyb v paměti</div></div>
                    </button>
                    <button onClick={() => setMode(AppMode.BROWSER)} className={getMenuButtonClass("bg-white hover:bg-indigo-50 text-indigo-700")}>
                        <div className="bg-indigo-100 p-3 rounded-full"><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg></div>
                        <div><div className="font-bold text-lg">Prohlížet otázky</div><div className="text-sm text-gray-500 font-normal">Databáze {currentQuestions.length} otázek</div></div>
                    </button>
                </div>
            </div>
        </div>
      )}

      {subject && mode === AppMode.BROWSER && (
        <div className="max-w-4xl mx-auto p-4 md:p-8">
            <div className="flex flex-col md:flex-row justify-between items-center mb-8 gap-4 sticky top-0 bg-slate-50 py-4 z-20">
                <button onClick={() => setMode(AppMode.MENU)} className="inline-flex items-center gap-2 px-4 py-2 rounded-lg bg-white border border-gray-200 text-gray-600 hover:text-blue-600 transition-colors shadow-sm">
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
                    Zpět
                </button>
                <div className="relative flex-1 w-full max-w-md">
                    <input 
                        type="text" 
                        placeholder="Hledat otázku (text nebo ID)..." 
                        value={browserSearch}
                        onChange={(e) => setBrowserSearch(e.target.value)}
                        className="w-full pl-10 pr-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-blue-500 outline-none shadow-sm"
                    />
                    <svg className="w-5 h-5 absolute left-3 top-3.5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                </div>
                <div className="text-sm text-gray-500 font-medium whitespace-nowrap">
                    Nalezeno: {filteredBrowserQuestions.length}
                </div>
            </div>

            <div className="space-y-4">
                {filteredBrowserQuestions.length > 0 ? (
                    filteredBrowserQuestions.map(q => (
                        <BrowserQuestionItem 
                            key={q.id} 
                            question={q} 
                            isExpanded={expandedIds.has(q.id)} 
                            onToggle={() => toggleExpand(q.id)}
                            onReportRequest={(id) => setReportingQuestionId(id)}
                        />
                    ))
                ) : (
                    <div className="text-center py-20 bg-white rounded-2xl border border-dashed border-gray-300">
                        <p className="text-gray-400">Žádné otázky neodpovídají hledání.</p>
                    </div>
                )}
            </div>
        </div>
      )}

      {subject && mode === AppMode.BATTLE && currentUser && (
          <BattleManager 
            currentUser={currentUser} 
            subject={subject} 
            stats={statsSPS}
            onExit={() => setMode(AppMode.MENU)} 
          />
      )}

      {subject && (mode === AppMode.MOCK_TEST || mode === AppMode.TRAINING || mode === AppMode.MISTAKES || mode === AppMode.REVIEW) && (
          <TestRunner key={subject + mode} mode={mode} mistakeIds={mode === AppMode.MISTAKES ? currentMistakes : undefined} onComplete={handleTestComplete} onExit={() => setMode(AppMode.MENU)} onReportRequest={(id) => setReportingQuestionId(id)} initialQuestionsForMode={currentQuestions} initialQuestions={mode === AppMode.REVIEW ? lastTestQuestions : undefined} initialAnswers={mode === AppMode.REVIEW ? lastUserAnswers : undefined} subject={subject} />
      )}
    </div>
  );
};

export default App;

// added comment above fix: Always use the direct import for GoogleGenAI as per guidelines
import { GoogleGenAI } from "@google/genai";
import type { GenerateContentResponse, Chat } from "@google/genai";
import { Question } from "../types";

export const getExplanation = async (question: Question): Promise<string> => {
  try {
    // added comment above fix: Create a new GoogleGenAI instance right before making an API call to ensure it always uses the most up-to-date API key from the dialog. Use the named parameter.
    const ai = new GoogleGenAI({apiKey: process.env.API_KEY});

    // added comment above fix: Use gemini-3-pro-preview for complex STEM/engineering tasks
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `Otázka: ${question.text}
Možnosti:
${question.options.map((opt, i) => `${i}) ${opt}`).join('\n')}
Správná odpověď: ${question.options[question.correctAnswerIndex]}`,
      config: {
        systemInstruction: "Jsi odborný učitel strojírenství. Vysvětli stručně a jasně tuto maturitní otázku a proč je správná právě uvedená odpověď. Vysvětlení napiš v češtině, srozumitelně pro studenta střední odborné školy. Zaměř se na technickou podstatu.",
        temperature: 0.7,
        topP: 0.95,
        topK: 40,
      }
    });

    // added comment above fix: Access .text property directly (not a method)
    return response.text || "Nepodařilo se vygenerovat vysvětlení.";
  } catch (error: any) {
    console.error("Gemini API Error:", error);
    // added comment above fix: Handle "Requested entity was not found" error by prompting for a new key as per guidelines
    if (error?.message?.includes("Requested entity was not found")) {
      if (typeof window !== 'undefined' && (window as any).aistudio?.openSelectKey) {
        (window as any).aistudio.openSelectKey();
      }
      throw new Error("API_KEY_NOT_FOUND");
    }
    return "Omlouvám se, ale při komunikaci s AI došlo k chybě. Zkontrolujte prosím své připojení nebo API klíč.";
  }
};

export const chatWithTutor = async (history: { role: 'user' | 'model', text: string }[], message: string): Promise<string> => {
  try {
    // added comment above fix: Create a new instance right before the call
    const ai = new GoogleGenAI({apiKey: process.env.API_KEY});

    // added comment above fix: Use the Chat interface for multi-turn conversations
    const chat: Chat = ai.chats.create({
      model: 'gemini-3-pro-preview',
      config: {
        systemInstruction: "Jsi přátelský a vysoce odborný tutor pro strojírenské obory (SPS a STT). Odpovídej věcně, technicky správně a pomáhej studentům pochopit látku k maturitě.",
      },
      history: history.map(h => ({ role: h.role, parts: [{ text: h.text }] })),
    });

    // added comment above fix: sendMessage only accepts the message parameter
    const response: GenerateContentResponse = await chat.sendMessage({ message });

    return response.text || "Tutor neodpovídá.";
  } catch (error: any) {
    console.error("Chat Error:", error);
    if (error?.message?.includes("Requested entity was not found")) {
      if (typeof window !== 'undefined' && (window as any).aistudio?.openSelectKey) {
        (window as any).aistudio.openSelectKey();
      }
    }
    return "Chyba v chatu.";
  }
};

