import React, { useState, useEffect } from 'react';
import { db } from '../firebaseConfig';
import { doc, onSnapshot, updateDoc } from 'firebase/firestore';
import { BattleRoom, Question } from '../types';
import { AppUser } from '../users';
import { QUESTIONS_SPS } from '../constants';
import { QuestionCard } from './QuestionCard';

interface Props {
  room: BattleRoom;
  currentUser: AppUser;
  onExit: () => void;
  stats: any;
}

export const BattleArena: React.FC<Props> = ({ room, currentUser, onExit, stats }) => {
  const [battleData, setBattleData] = useState<BattleRoom>(room);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [currentQuestions, setCurrentQuestions] = useState<Question[]>([]);
  const [finished, setFinished] = useState(false);
  const [myScore, setMyScore] = useState(0);

  useEffect(() => {
    const qs = room.questions.map(id => QUESTIONS_SPS.find(q => q.id === id)!).filter(Boolean);
    setCurrentQuestions(qs);

    const incrementBattleLimit = async () => {
        const userRef = doc(db, "users", currentUser.uid);
        const today = new Date().toISOString().split('T')[0];
        const newCount = stats?.lastBattleDate === today ? (stats?.battlesPlayedToday || 0) + 1 : 1;
        await updateDoc(userRef, {
            "statsSPS.battlesPlayedToday": newCount,
            "statsSPS.lastBattleDate": today
        });
    };
    incrementBattleLimit();
  }, []);

  useEffect(() => {
    const unsub = onSnapshot(doc(db, "battles", room.id), (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data() as BattleRoom;
        setBattleData(data);

        const players = Object.values(data.players);
        if (players.length === 2 && players.every(p => p.finished)) {
            setFinished(true);
        }
      }
    });
    return () => unsub();
  }, [room.id]);

  const handleAnswer = async (qId: number, idx: number, isCorrect: boolean) => {
    const newScore = isCorrect ? myScore + 1 : myScore;
    setMyScore(newScore);

    const isLast = currentIndex === currentQuestions.length - 1;
    const newProgress = currentIndex + 1;

    // Aktualizace postupu v DB
    await updateDoc(doc(db, "battles", room.id), {
      [`players.${currentUser.uid}.progress`]: newProgress,
      [`players.${currentUser.uid}.score`]: newScore,
      [`players.${currentUser.uid}.finished`]: isLast
    });

    if (!isLast) {
      setCurrentIndex(prev => prev + 1);
    }
  };

  const opponent = Object.values(battleData.players).find(p => p.uid !== currentUser.uid);
  const me = battleData.players[currentUser.uid];

  if (finished) {
    const winner = me.score > (opponent?.score || 0) ? 'win' : me.score < (opponent?.score || 0) ? 'loss' : 'draw';
    return (
        <div className="max-w-xl mx-auto mt-20 text-center p-8 bg-white rounded-3xl shadow-2xl border border-gray-100 animate-in zoom-in duration-300">
            <div className={`w-24 h-24 mx-auto mb-6 rounded-full flex items-center justify-center text-4xl ${winner === 'win' ? 'bg-yellow-100' : winner === 'loss' ? 'bg-red-100' : 'bg-gray-100'}`}>
                {winner === 'win' ? '🏆' : winner === 'loss' ? '💀' : '🤝'}
            </div>
            <h2 className="text-4xl font-black mb-2">
                {winner === 'win' ? 'Vítězství!' : winner === 'loss' ? 'Prohra' : 'Remíza'}
            </h2>
            <p className="text-gray-500 mb-8">Souboj SPS ukončen</p>

            <div className="grid grid-cols-2 gap-4 mb-8">
                <div className="p-4 bg-blue-50 rounded-2xl">
                    <p className="text-xs text-blue-600 uppercase font-bold mb-1">Ty</p>
                    <p className="text-3xl font-black text-blue-900">{me.score}</p>
                </div>
                <div className="p-4 bg-red-50 rounded-2xl">
                    <p className="text-xs text-red-600 uppercase font-bold mb-1">{opponent?.displayName || 'Soupeř'}</p>
                    <p className="text-3xl font-black text-red-900">{opponent?.score || 0}</p>
                </div>
            </div>

            <button onClick={onExit} className="w-full py-4 bg-gray-900 text-white font-bold rounded-2xl hover:bg-black transition-all">
                Zpět do menu
            </button>
        </div>
    );
  }

  const currentQ = currentQuestions[currentIndex];

  return (
    <div className="max-w-4xl mx-auto w-full px-4 pt-6">
      {/* Real-time Progress bars */}
      <div className="bg-white rounded-2xl shadow-md p-4 mb-8 sticky top-4 z-20 border border-gray-100">
        <div className="space-y-4">
            {/* Moje lajna */}
            <div>
                <div className="flex justify-between text-xs font-bold mb-1">
                    <span className="text-blue-600">TY ({me.score} b.)</span>
                    <span>{currentIndex}/{currentQuestions.length}</span>
                </div>
                <div className="w-full h-3 bg-gray-100 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 transition-all duration-500" style={{width: `${(currentIndex / currentQuestions.length) * 100}%`}}></div>
                </div>
            </div>
            {/* Soupeřova lajna */}
            <div>
                <div className="flex justify-between text-xs font-bold mb-1">
                    <span className="text-red-600">{opponent?.displayName?.toUpperCase() || 'SOUPEŘ'} ({(opponent?.score || 0)} b.)</span>
                    <span>{opponent?.progress || 0}/{currentQuestions.length}</span>
                </div>
                <div className="w-full h-3 bg-gray-100 rounded-full overflow-hidden">
                    <div className="h-full bg-red-500 transition-all duration-500" style={{width: `${((opponent?.progress || 0) / currentQuestions.length) * 100}%`}}></div>
                </div>
            </div>
        </div>
      </div>

      {currentQ && !me.finished ? (
          <QuestionCard 
            key={currentIndex}
            question={currentQ}
            mode={'MOCK_TEST' as any}
            onAnswer={handleAnswer}
            showFeedback={false}
          />
      ) : (
          <div className="text-center p-12 bg-white rounded-2xl shadow-sm border border-gray-100">
              <div className="animate-bounce text-4xl mb-4">🏁</div>
              <h3 className="text-xl font-bold">Máš hotovo!</h3>
              <p className="text-gray-500">Čekáme, až soupeř dokončí test...</p>
          </div>
      )}
    </div>
  );
};

