export default App;

import React, { useState, useEffect, useRef } from 'react';
import { db } from '../firebaseConfig';
import { doc, onSnapshot, updateDoc } from 'firebase/firestore';
import { BattleRoom, Question, AppMode, BattlePlayerData } from '../types';
import { AppUser } from '../users';
import { QUESTIONS_SPS } from '../constants';
import { QuestionCard } from './QuestionCard';

interface Props {
  room: BattleRoom;
  currentUser: AppUser;
  onExit: () => void;
  stats: any;
}

export const BattleArena: React.FC<Props> = ({ room, currentUser, onExit, stats }) => {
  const [battleData, setBattleData] = useState<BattleRoom>(room);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [currentQuestions, setCurrentQuestions] = useState<Question[]>([]);
  const [finished, setFinished] = useState(false);
  const [myScore, setMyScore] = useState(0);
  const [timeLeft, setTimeLeft] = useState<number | null>(null);

  // added comment above fix: Use 'any' instead of 'NodeJS.Timeout' to avoid namespace issues in browser environment.
  const timerRef = useRef<any>(null);

  // Inicializace otázek při startu
  useEffect(() => {
    const qs = room.questions.map(id => QUESTIONS_SPS.find(q => q.id === id)!).filter(Boolean);
    setCurrentQuestions(qs);
  }, [room.questions]);

  // Sledování změn v bitvě (postup soupeře, stav hry)
  useEffect(() => {
    const unsub = onSnapshot(doc(db, "battles", room.id), (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data() as BattleRoom;
        setBattleData(data);

        // added comment above fix: Explicitly cast players to BattlePlayerData array to avoid 'unknown' type errors.
        const players = Object.values(data.players) as BattlePlayerData[];
        // Pokud jsou oba hotoví, nebo je stav v DB 'FINISHED', ukončíme to lokálně
        if ((players.length === 2 && players.every(p => p.finished)) || data.status === 'FINISHED') {
            setFinished(true);
            if (timerRef.current) clearInterval(timerRef.current);
        }
      }
    });
    return () => {
        unsub();
        if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [room.id]);

  // Logika časovače (30 minut)
  useEffect(() => {
    if (!battleData.expiresAt || finished) return;

    const updateTimer = () => {
        const now = Date.now();
        const diff = Math.max(0, Math.floor((battleData.expiresAt! - now) / 1000));
        setTimeLeft(diff);

        if (diff <= 0) {
            handleTimeOut();
        }
    };

    updateTimer();
    timerRef.current = setInterval(updateTimer, 1000);

    return () => {
        if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [battleData.expiresAt, finished]);

  const handleTimeOut = async () => {
    if (timerRef.current) clearInterval(timerRef.current);

    // Pokud čas vypršel a já ještě nejsem hotový, označím se za hotového
    try {
        await updateDoc(doc(db, "battles", room.id), {
            [`players.${currentUser.uid}.finished`]: true,
            status: 'FINISHED'
        });
    } catch (e) {
        console.error(e);
    }
    setFinished(true);
  };

  const handleAnswer = async (qId: number, idx: number, isCorrect: boolean) => {
    const newScore = isCorrect ? myScore + 1 : myScore;
    setMyScore(newScore);

    const isLast = currentIndex === currentQuestions.length - 1;
    const newProgress = currentIndex + 1;

    // Odeslání postupu do Firebase
    try {
        await updateDoc(doc(db, "battles", room.id), {
            [`players.${currentUser.uid}.progress`]: newProgress,
            [`players.${currentUser.uid}.score`]: newScore,
            [`players.${currentUser.uid}.finished`]: isLast
        });
    } catch (e) {
        console.error("Chyba při ukládání odpovědi:", e);
    }

    if (!isLast) {
      setCurrentIndex(prev => prev + 1);
    }
  };

  const handleSurrender = () => {
    // 1. Zeptat se, jestli to vážně chce (systémové okno)
    const confirmExit = window.confirm("Opravdu se chceš vzdát a odejít z bitvy? Tvůj aktuální výsledek bude uložen jako konečný.");

    if (confirmExit) {
        // 2. Okamžitě odejít v UI (aby uživatel nečekal)
        onExit();

        // 3. Na pozadí aktualizovat databázi, aby soupeř viděl, že jsi skončil
        updateDoc(doc(db, "battles", room.id), {
            [`players.${currentUser.uid}.finished`]: true
        }).catch(err => console.error("Background update failed:", err));
    }
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s < 10 ? '0' : ''}${s}`;
  };

  // added comment above fix: Explicitly cast players values to BattlePlayerData to resolve 'unknown' property access errors.
  const playersList = Object.values(battleData.players) as BattlePlayerData[];
  const opponent = playersList.find(p => p.uid !== currentUser.uid);
  const me = battleData.players[currentUser.uid] as BattlePlayerData | undefined;

  // Ochrana před neexistujícími daty o hráči při načítání
  if (!me) return <div className="text-center mt-20 text-gray-500 font-medium">Načítám data bitvy...</div>;

  // Obrazovka s výsledky a statistikami po skončení
  if (finished) {
    const myFinalScore = me.score;
    const oppFinalScore = opponent?.score || 0;
    const winner = myFinalScore > oppFinalScore ? 'win' : myFinalScore < oppFinalScore ? 'loss' : 'draw';

    return (
        <div className="max-w-xl mx-auto mt-20 text-center p-8 bg-white rounded-3xl shadow-2xl border border-gray-100 animate-in zoom-in duration-300">
            <div className={`w-24 h-24 mx-auto mb-6 rounded-full flex items-center justify-center text-4xl ${winner === 'win' ? 'bg-yellow-100' : winner === 'loss' ? 'bg-red-100' : 'bg-gray-100'}`}>
                {winner === 'win' ? '🏆' : winner === 'loss' ? '💀' : '🤝'}
            </div>
            <h2 className="text-4xl font-black mb-2">
                {winner === 'win' ? 'Vítězství!' : winner === 'loss' ? 'Prohra' : 'Remíza'}
            </h2>
            <p className="text-gray-500 mb-8 uppercase tracking-widest text-xs font-bold">Bitva SPS dokončena</p>

            <div className="grid grid-cols-2 gap-6 mb-8">
                <div className={`p-6 rounded-3xl border-2 ${winner === 'win' ? 'border-yellow-200 bg-yellow-50/30' : 'border-blue-100 bg-blue-50/30'}`}>
                    <p className="text-xs text-blue-600 uppercase font-black mb-2">Ty</p>
                    <p className="text-4xl font-black text-blue-900">{myFinalScore}</p>
                    <p className="text-[10px] text-gray-400 mt-1">{Math.round((myFinalScore / (currentQuestions.length || 1)) * 100)}% úspěšnost</p>
                </div>
                <div className={`p-6 rounded-3xl border-2 ${winner === 'loss' ? 'border-yellow-200 bg-yellow-50/30' : 'border-red-100 bg-red-50/30'}`}>
                    <p className="text-xs text-red-600 uppercase font-black mb-2">{opponent?.displayName || 'Soupeř'}</p>
                    <p className="text-4xl font-black text-red-900">{oppFinalScore}</p>
                    <p className="text-[10px] text-gray-400 mt-1">{Math.round((oppFinalScore / (currentQuestions.length || 20)) * 100)}% úspěšnost</p>
                </div>
            </div>

            <div className="bg-gray-50 p-4 rounded-2xl mb-8 flex justify-around text-sm text-gray-600 font-medium">
                <div className="flex flex-col">
                    <span className="text-[10px] text-gray-400 uppercase">Otázek</span>
                    <span>{currentQuestions.length}</span>
                </div>
                <div className="w-px bg-gray-200"></div>
                <div className="flex flex-col">
                    <span className="text-[10px] text-gray-400 uppercase">Mód</span>
                    <span>1v1 Bitva</span>
                </div>
            </div>

            <button type="button" onClick={onExit} className="w-full py-4 bg-gray-900 text-white font-bold rounded-2xl hover:bg-black transition-all shadow-xl active:scale-[0.98]">
                Zpět do hlavního menu
            </button>
        </div>
    );
  }

  const currentQ = currentQuestions[currentIndex];

  return (
    <div className="max-w-4xl mx-auto w-full px-4 pt-6">
      {/* Horní lišta s časovačem a stavem soupeře */}
      <div className="bg-white rounded-2xl shadow-lg p-4 mb-8 sticky top-4 z-20 border border-gray-100 flex flex-col gap-4">
        <div className="flex items-center justify-between px-2">
            <div className="flex items-center gap-2">
                <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
                <span className="text-[10px] font-black text-gray-400 uppercase tracking-tighter">Live Souboj</span>
            </div>
            {timeLeft !== null && (
                <div className={`px-4 py-1 rounded-full font-mono text-lg font-bold flex items-center gap-2 ${timeLeft < 60 ? 'bg-red-100 text-red-600 animate-pulse' : 'bg-gray-100 text-gray-700'}`}>
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                    {formatTime(timeLeft)}
                </div>
            )}
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {/* Můj progres */}
            <div>
                <div className="flex justify-between text-[10px] font-black mb-1">
                    <span className="text-blue-600">TY • {me.score} b.</span>
                    <span className="text-gray-400">{currentIndex}/{currentQuestions.length}</span>
                </div>
                <div className="w-full h-2 bg-gray-100 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 transition-all duration-500" style={{width: `${(currentIndex / (currentQuestions.length || 1)) * 100}%`}}></div>
                </div>
            </div>
            {/* Progres soupeře */}
            <div>
                <div className="flex justify-between text-[10px] font-black mb-1">
                    <span className="text-red-600">{opponent?.displayName?.toUpperCase() || 'ČEKÁM...'} • {(opponent?.score || 0)} b.</span>
                    <span className="text-gray-400">{opponent?.progress || 0}/{currentQuestions.length}</span>
                </div>
                <div className="w-full h-2 bg-gray-100 rounded-full overflow-hidden">
                    <div className="h-full bg-red-500 transition-all duration-500" style={{width: `${((opponent?.progress || 0) / (currentQuestions.length || 1)) * 100}%`}}></div>
                </div>
            </div>
        </div>
      </div>

      {currentQ && !me.finished ? (
          <div className="flex flex-col items-center">
            <QuestionCard 
                key={currentIndex}
                question={currentQ}
                mode={AppMode.MOCK_TEST}
                onAnswer={handleAnswer}
                showFeedback={false}
            />

            {/* Tlačítko Vzdát se */}
            <button 
                type="button"
                onClick={handleSurrender}
                className="mt-6 px-8 py-3 text-red-600 hover:text-white font-bold border-2 border-red-100 hover:border-red-600 hover:bg-red-600 rounded-2xl transition-all shadow-sm flex items-center gap-2 group"
            >
                <svg className="w-5 h-5 group-hover:animate-bounce" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
                </svg>
                Vzdát se a odejít
            </button>
          </div>
      ) : (
          <div className="text-center p-12 bg-white rounded-3xl shadow-sm border border-gray-100 animate-in fade-in duration-700">
              <div className="relative w-20 h-20 mx-auto mb-6">
                <div className="absolute inset-0 bg-blue-100 rounded-full animate-ping opacity-25"></div>
                <div className="relative w-20 h-20 bg-blue-50 rounded-full flex items-center justify-center text-4xl">🏁</div>
              </div>
              <h3 className="text-2xl font-bold mb-2">Máš dobojováno!</h3>
              <p className="text-gray-500 mb-8 max-w-xs mx-auto">Tvé odpovědi jsou uloženy. Čekáme, až soupeř dokončí test nebo až vyprší časový limit.</p>

              <div className="flex flex-col gap-3">
                <div className="p-4 bg-gray-50 rounded-2xl border border-gray-100">
                    <p className="text-xs font-bold text-gray-400 uppercase mb-1">Tvůj výsledek</p>
                    <p className="text-2xl font-black text-gray-800">{me.score} / {currentQuestions.length}</p>
                </div>
                <button type="button" onClick={onExit} className="mt-4 text-sm text-blue-600 font-bold hover:underline">
                    Zrušit čekání a jít do menu
                </button>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Question } from '../types';
import { QuestionCard } from './QuestionCard';
import { AppMode } from '../types';
import { db, auth } from '../firebaseConfig';
import { doc, getDoc, setDoc } from 'firebase/firestore';

interface Props {
  initialQuestions: Question[];
  onExit: () => void;
  currentUser: any;
}

export const SuddenDeathGame: React.FC<Props> = ({ initialQuestions, onExit, currentUser }) => {
  const [currentQuestion, setCurrentQuestion] = useState<Question | null>(null);
  const [streak, setStreak] = useState(0);
  const [timeLeft, setTimeLeft] = useState(30);
  const [gameOver, setGameOver] = useState(false);
  const [usedQuestionIds, setUsedQuestionIds] = useState<Set<number>>(new Set());
  const [bestStreak, setBestStreak] = useState(0);

  // added comment above fix: Use 'any' instead of 'NodeJS.Timeout' to avoid namespace errors.
  const timerRef = useRef<any>(null);

  // Načtení nejlepšího streaku při startu
  useEffect(() => {
    const loadBestStreak = async () => {
      if (currentUser && db) {
        const userRef = doc(db, "users", currentUser.uid);
        const snap = await getDoc(userRef);
        if (snap.exists()) {
          setBestStreak(snap.data().statsSPS?.bestStreak || 0);
        }
      }
    };
    loadBestStreak();
    nextQuestion();
    return () => stopTimer();
  }, []);

  const stopTimer = () => {
    if (timerRef.current) clearInterval(timerRef.current);
  };

  const startTimer = () => {
    stopTimer();
    setTimeLeft(30);
    timerRef.current = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          handleGameOver();
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
  };

  const nextQuestion = () => {
    // Vybrat náhodnou otázku, která ještě nebyla
    const available = initialQuestions.filter(q => !usedQuestionIds.has(q.id));

    if (available.length === 0) {
      // Došly otázky (teoreticky nemožné v tomto módu, ale pro jistotu)
      setUsedQuestionIds(new Set()); // Reset
      const random = initialQuestions[Math.floor(Math.random() * initialQuestions.length)];
      setCurrentQuestion(random);
    } else {
      const random = available[Math.floor(Math.random() * available.length)];
      setCurrentQuestion(random);
      setUsedQuestionIds(prev => new Set(prev).add(random.id));
    }

    startTimer();
  };

  const handleGameOver = async () => {
    stopTimer();
    setGameOver(true);

    // Uložení nového rekordu
    if (streak > bestStreak && currentUser) {
      setBestStreak(streak);
      try {
        const userRef = doc(db, "users", currentUser.uid);
        await setDoc(userRef, {
          statsSPS: {
            bestStreak: streak
          }
        }, { merge: true });
      } catch (e) {
        console.error("Failed to save streak", e);
      }
    }
  };

  const handleAnswer = (qId: number, idx: number, isCorrect: boolean) => {
    if (isCorrect) {
      setStreak(s => s + 1);
      nextQuestion();
    } else {
      handleGameOver();
    }
  };

  if (gameOver) {
    return (
      <div className="max-w-md mx-auto mt-20 p-8 bg-white rounded-3xl shadow-2xl border-4 border-red-100 text-center animate-in zoom-in duration-300">
        <div className="w-24 h-24 mx-auto mb-6 bg-red-100 rounded-full flex items-center justify-center text-5xl">
          ☠️
        </div>
        <h2 className="text-4xl font-black text-gray-900 mb-2">KONEC HRY</h2>
        <p className="text-gray-500 mb-8 font-medium">Jedna chyba a jsi venku...</p>

        <div className="grid grid-cols-2 gap-4 mb-8">
          <div className="p-4 bg-gray-50 rounded-2xl border border-gray-200">
            <p className="text-xs uppercase text-gray-400 font-bold mb-1">Dnešní Streak</p>
            <p className="text-3xl font-black text-blue-600">{streak}</p>
          </div>
          <div className="p-4 bg-yellow-50 rounded-2xl border border-yellow-200">
            <p className="text-xs uppercase text-yellow-600 font-bold mb-1">Tvůj Rekord</p>
            <p className="text-3xl font-black text-yellow-700">{Math.max(streak, bestStreak)}</p>
          </div>
        </div>

        <button 
          onClick={() => {
            setGameOver(false);
            setStreak(0);
            setUsedQuestionIds(new Set());
            nextQuestion();
          }}
          className="w-full py-4 bg-red-600 text-white font-bold rounded-xl hover:bg-red-700 transition-all shadow-lg shadow-red-200 mb-3"
        >
          Zkusit znovu
        </button>
        <button 
          onClick={onExit}
          className="w-full py-3 text-gray-500 font-bold hover:text-gray-800 transition-colors"
        >
          Zpět do menu
        </button>
      </div>
    );
  }

  if (!currentQuestion) return <div className="text-center mt-20">Načítám arénu...</div>;

  return (
    <div className="max-w-4xl mx-auto w-full px-4 pt-6">
      {/* HUD */}
      <div className="flex items-center justify-between mb-6 bg-gray-900 text-white p-4 rounded-2xl shadow-lg">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-full bg-red-600 flex items-center justify-center font-bold text-lg border-2 border-red-400">
            {streak}
          </div>
          <div className="flex flex-col">
            <span className="text-xs text-gray-400 uppercase font-bold tracking-wider">Streak</span>
            <span className="font-bold text-red-400">NÁHLÁ SMRT</span>
          </div>
        </div>

        <div className="flex items-center gap-2">
           <span className="text-xs text-gray-400 font-mono">ČAS:</span>
           <span className={`text-2xl font-mono font-black ${timeLeft <= 5 ? 'text-red-500 animate-pulse' : 'text-white'}`}>
             {timeLeft}s
           </span>
        </div>
      </div>

      {/* Progress bar pro čas */}
      <div className="w-full h-2 bg-gray-200 rounded-full mb-8 overflow-hidden">
        <div 
          className={`h-full transition-all duration-1000 ease-linear ${timeLeft <= 10 ? 'bg-red-600' : 'bg-blue-600'}`}
          style={{ width: `${(timeLeft / 30) * 100}%` }}
        ></div>
      </div>

      <QuestionCard 
        question={currentQuestion}
        mode={AppMode.MOCK_TEST} // Používáme mock test mód pro vzhled (bez okamžitého vyhodnocení v kartě)
        onAnswer={handleAnswer}
        showFeedback={false}
      />

      <div className="text-center mt-8">
        <button onClick={onExit} className="text-gray-400 hover:text-red-500 text-sm font-medium transition-colors">
          Vzdát to a odejít
        </button>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { Subject, LeaderboardUser } from '../types';
import { db } from '../firebaseConfig';
import { collection, getDocs } from 'firebase/firestore';

interface Props {
  subject: Subject;
  onBack?: () => void;
  variant?: 'full' | 'compact'; // 'full' = celá stránka, 'compact' = widget do menu
}

type SortType = 'SCORE' | 'GRIND' | 'STREAK';

export const Leaderboard: React.FC<Props> = ({ subject, onBack, variant = 'full' }) => {
  const [users, setUsers] = useState<LeaderboardUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [sortType, setSortType] = useState<SortType>('SCORE');

  useEffect(() => {
    const fetchUsers = async () => {
      try {
        if (!db) return;
        const querySnapshot = await getDocs(collection(db, "users"));
        const loadedUsers: LeaderboardUser[] = [];

        querySnapshot.forEach((doc) => {
          const data = doc.data();
          if (subject === 'SPS' && data.statsSPS) {
            loadedUsers.push({ displayName: data.displayName || 'Neznámý', statsSPS: data.statsSPS });
          } else if (subject === 'STT' && data.statsSTT) {
            loadedUsers.push({ displayName: data.displayName || 'Neznámý', statsSTT: data.statsSTT });
          }
        });

        setUsers(loadedUsers);
      } catch (error) {
        console.error("Chyba při načítání žebříčku:", error instanceof Error ? error.message : error);
      } finally {
        setLoading(false);
      }
    };

    fetchUsers();
  }, [subject]);

  const getStats = (user: LeaderboardUser) => {
    return subject === 'SPS' ? user.statsSPS : user.statsSTT;
  };

  const sortedUsers = [...users].sort((a, b) => {
    const statsA = getStats(a);
    const statsB = getStats(b);

    if (!statsA || !statsB) return 0;

    if (sortType === 'SCORE') {
      // Primárně podle nejlepšího skóre
      if (statsB.bestScorePercent !== statsA.bestScorePercent) {
        return statsB.bestScorePercent - statsA.bestScorePercent;
      }
      return (statsB.bestStreak || 0) - (statsA.bestStreak || 0);
    } else if (sortType === 'GRIND') {
      // Primárně podle počtu testů
      if (statsB.testsTaken !== statsA.testsTaken) {
        return statsB.testsTaken - statsA.testsTaken;
      }
      return statsB.bestScorePercent - statsA.bestScorePercent;
    } else {
      // Primárně podle streaku
      const streakA = statsA.bestStreak || 0;
      const streakB = statsB.bestStreak || 0;
      if (streakB !== streakA) return streakB - streakA;
      return statsB.bestScorePercent - statsA.bestScorePercent;
    }
  });

  // V kompaktním režimu ukážeme jen TOP 5
  const displayUsers = variant === 'compact' ? sortedUsers.slice(0, 5) : sortedUsers;

  const getMedalColor = (index: number) => {
    if (index === 0) return "bg-yellow-100 text-yellow-700 border-yellow-300";
    if (index === 1) return "bg-gray-100 text-gray-700 border-gray-300";
    if (index === 2) return "bg-orange-100 text-orange-800 border-orange-300";
    return "bg-white text-gray-600 border-gray-100";
  };

  // Helper funkce pro výpočet průměru
  const calculateAverage = (totalPoints: number, totalMaxPoints: number) => {
      if (!totalMaxPoints || totalMaxPoints === 0) return 0;
      return Math.round((totalPoints / totalMaxPoints) * 100);
  };

  return (
    <div className={`${variant === 'full' ? 'max-w-5xl mx-auto p-4 min-h-screen' : 'w-full h-full flex flex-col'}`}>

      {/* Header */}
      <div className={`flex items-center justify-between ${variant === 'full' ? 'mb-8' : 'mb-4'}`}>
        {variant === 'full' && onBack && (
            <button 
                onClick={onBack}
                className="flex items-center text-gray-500 hover:text-gray-900 transition-colors"
            >
                <svg className="w-6 h-6 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
                Zpět
            </button>
        )}
        <h1 className={`font-bold ${variant === 'full' ? 'text-2xl' : 'text-lg'} ${subject === 'SPS' ? 'text-blue-600' : 'text-orange-600'}`}>
            {variant === 'full' ? `Žebříček ${subject}` : `Top ${subject}`}
        </h1>
      </div>

      {/* Přepínač řazení pouze pro plnou verzi */}
      {variant === 'full' && (
        <div className="flex flex-col sm:flex-row justify-between items-center gap-4 mb-6 bg-white p-4 rounded-xl border border-gray-100 shadow-sm">
            <div className="text-gray-500 text-sm">
                Řadit podle:
            </div>
            <div className="flex flex-wrap gap-2 bg-gray-100 p-1 rounded-lg">
                <button 
                    onClick={() => setSortType('SCORE')}
                    className={`px-4 py-2 rounded-md font-medium text-sm transition-all flex items-center gap-2 ${sortType === 'SCORE' ? 'bg-white shadow-sm text-gray-900' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    <span>🎯</span> Nejlepší výkon
                </button>
                <button 
                    onClick={() => setSortType('GRIND')}
                    className={`px-4 py-2 rounded-md font-medium text-sm transition-all flex items-center gap-2 ${sortType === 'GRIND' ? 'bg-white shadow-sm text-gray-900' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    <span>💪</span> Počet testů
                </button>
                <button 
                    onClick={() => setSortType('STREAK')}
                    className={`px-4 py-2 rounded-md font-medium text-sm transition-all flex items-center gap-2 ${sortType === 'STREAK' ? 'bg-white shadow-sm text-gray-900' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    <span>🔥</span> Streak
                </button>
            </div>
        </div>
      )}

      {loading ? (
        <div className="text-center py-8 text-gray-400 text-sm">Načítám data...</div>
      ) : displayUsers.length === 0 ? (
        <div className="text-center py-8 bg-white rounded-xl shadow-sm border border-gray-200 border-dashed">
            <p className="text-gray-400 text-sm">Zatím žádné statistiky.</p>
        </div>
      ) : (
        <div className={`bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden flex-1 ${variant === 'compact' ? 'text-sm' : ''}`}>
            <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                    <thead>
                        <tr className="bg-gray-50 text-gray-500 text-xs uppercase tracking-wider border-b border-gray-200">
                            <th className={`${variant === 'compact' ? 'px-3 py-2' : 'px-6 py-4'} text-center w-8`}>#</th>
                            <th className={`${variant === 'compact' ? 'px-3 py-2' : 'px-6 py-4'}`}>Jméno</th>

                            {/* Sloupce - Plná verze (více místa) */}
                            {variant === 'full' && (
                                <>
                                    <th className="px-6 py-4 text-center">Testy</th>
                                    <th className="px-6 py-4 text-center">Průměr</th>
                                    <th className="px-6 py-4 text-center">Nejlepší</th>
                                    <th className="px-6 py-4 text-center text-red-600">Streak 🔥</th>
                                </>
                            )}

                            {/* Sloupce - Kompaktní verze */}
                            {variant === 'compact' && (
                                <>
                                    <th className="px-1 py-2 text-center text-[10px] w-10" title="Počet testů">Testy</th>
                                    <th className="px-1 py-2 text-center text-[10px] w-12" title="Nejlepší výsledek">Max</th>
                                    <th className="px-1 py-2 text-center text-[10px] w-10 text-red-600" title="Nejlepší streak">🔥</th>
                                </>
                            )}
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {displayUsers.map((user, index) => {
                            const stats = getStats(user)!;
                            const avgPercent = calculateAverage(stats.totalPoints, stats.totalMaxPoints);
                            const bestStreak = stats.bestStreak || 0;

                            return (
                                <tr key={index} className="hover:bg-gray-50 transition-colors">
                                    <td className={`${variant === 'compact' ? 'px-3 py-2' : 'px-6 py-4'} text-center`}>
                                        <div className={`${variant === 'compact' ? 'w-6 h-6 text-xs' : 'w-8 h-8'} rounded-full flex items-center justify-center mx-auto font-bold border ${getMedalColor(index)}`}>
                                            {index + 1}
                                        </div>
                                    </td>
                                    <td className={`${variant === 'compact' ? 'px-3 py-2' : 'px-6 py-4'} font-medium text-gray-900 truncate max-w-[100px] sm:max-w-none`}>
                                        {user.displayName}
                                    </td>

                                    {/* Plná verze tabulky */}
                                    {variant === 'full' && (
                                        <>
                                            <td className="px-6 py-4 text-center text-gray-600">
                                                {stats.testsTaken}x
                                            </td>
                                            <td className="px-6 py-4 text-center">
                                                <span className={`inline-block px-2 py-1 rounded text-sm ${avgPercent >= 80 ? 'bg-green-100 text-green-800' : avgPercent >= 50 ? 'bg-blue-50 text-blue-800' : 'bg-gray-100 text-gray-600'}`}>
                                                    {avgPercent}%
                                                </span>
                                            </td>
                                            <td className="px-6 py-4 text-center font-bold text-gray-800 text-lg">
                                                {Math.round(stats.bestScorePercent)}%
                                            </td>
                                            <td className="px-6 py-4 text-center font-black text-red-600 text-lg">
                                                {bestStreak}
                                            </td>
                                        </>
                                    )}

                                    {/* Kompaktní verze widgetu */}
                                    {variant === 'compact' && (
                                        <>
                                            <td className="px-1 py-2 text-center text-xs text-gray-500">
                                                {stats.testsTaken}
                                            </td>
                                            <td className="px-1 py-2 text-center text-sm font-bold text-gray-800">
                                                {Math.round(stats.bestScorePercent)}%
                                            </td>
                                            <td className="px-1 py-2 text-center text-sm font-bold text-red-600">
                                                {bestStreak}
                                            </td>
                                        </>
                                    )}
                                </tr>
                            );
                        })}
                    </tbody>
                </table>
            </div>
            {variant === 'compact' && sortedUsers.length > 5 && (
                <div 
                    onClick={onBack} 
                    className="bg-gray-50 p-2 text-center text-xs text-gray-500 hover:text-blue-600 hover:bg-gray-100 cursor-pointer border-t border-gray-100 transition-colors"
                >
                    Zobrazit všech {sortedUsers.length} studentů...
                </div>
            )}
        </div>
      )}
    </div>
  );
};

