            </div>
            <div className="flex flex-wrap gap-2">
                <button 
                    onClick={() => setSortType('SCORE')}
                    className={`px-4 py-2 rounded-lg font-bold text-sm transition-all flex items-center gap-2 border ${sortType === 'SCORE' ? 'bg-blue-600 text-white border-blue-600 shadow-md' : 'bg-white text-gray-600 border-gray-200 hover:bg-gray-50'}`}
                >
                    <span>🏆</span> Nejlepší %
                </button>
                <button 
                    onClick={() => setSortType('AVERAGE')}
                    className={`px-4 py-2 rounded-lg font-bold text-sm transition-all flex items-center gap-2 border ${sortType === 'AVERAGE' ? 'bg-blue-600 text-white border-blue-600 shadow-md' : 'bg-white text-gray-600 border-gray-200 hover:bg-gray-50'}`}
                >
                    <span>📊</span> Průměr
                </button>
                <button 
                    onClick={() => setSortType('GRIND')}
                    className={`px-4 py-2 rounded-lg font-bold text-sm transition-all flex items-center gap-2 border ${sortType === 'GRIND' ? 'bg-blue-600 text-white border-blue-600 shadow-md' : 'bg-white text-gray-600 border-gray-200 hover:bg-gray-50'}`}
                >
                    <span>💪</span> Počet testů
                </button>
                <button 
                    onClick={() => setSortType('STREAK')}
                    className={`px-4 py-2 rounded-lg font-bold text-sm transition-all flex items-center gap-2 border ${sortType === 'STREAK' ? 'bg-red-600 text-white border-red-600 shadow-md' : 'bg-white text-gray-600 border-gray-200 hover:bg-gray-50'}`}
                >
                    <span>🔥</span> Sudden Death
                </button>
            </div>
        </div>
      )}

      {loading ? (
        <div className="text-center py-8 text-gray-400 text-sm">Načítám data...</div>
      ) : displayUsers.length === 0 ? (
        <div className="text-center py-8 bg-white rounded-xl shadow-sm border border-gray-200 border-dashed">
            <p className="text-gray-400 text-sm">Zatím žádné statistiky.</p>
        </div>
      ) : (
        <div className={`bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden flex-1 ${variant === 'compact' ? 'text-sm' : ''}`}>
            <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                    <thead>
                        <tr className="bg-gray-50 text-gray-500 text-xs uppercase tracking-wider border-b border-gray-200">
                            <th className={`${variant === 'compact' ? 'px-3 py-2' : 'px-6 py-4'} text-center w-8`}>#</th>
                            <th className={`${variant === 'compact' ? 'px-3 py-2' : 'px-6 py-4'}`}>Jméno</th>

                            {/* Sloupce - Plná verze (více místa) */}
                            {variant === 'full' && (
                                <>
                                    <th className={`px-6 py-4 text-center whitespace-nowrap ${sortType === 'GRIND' ? 'text-blue-700 bg-blue-50 font-bold' : ''}`} title="Počet dokončených testů">Počet testů</th>
                                    <th className={`px-6 py-4 text-center whitespace-nowrap ${sortType === 'AVERAGE' ? 'text-blue-700 bg-blue-50 font-bold' : ''}`} title="Průměr ze všech testů">Průměr</th>
                                    <th className={`px-6 py-4 text-center whitespace-nowrap ${sortType === 'SCORE' ? 'text-blue-700 bg-blue-50 font-bold' : ''}`} title="Nejlepší výsledek testu">Nejlepší</th>
                                    <th className={`px-6 py-4 text-center whitespace-nowrap ${sortType === 'STREAK' ? 'text-red-700 bg-red-50 font-bold' : 'text-red-600'}`} title="Největší skóre v náhlé smrti">Sudden Death 🔥</th>
                                </>
                            )}

                            {/* Sloupce - Kompaktní verze */}
                            {variant === 'compact' && (
                                <>
                                    <th className="px-1 py-2 text-center text-[10px] w-8" title="Počet testů">Testy</th>
                                    <th className="px-1 py-2 text-center text-[10px] w-8" title="Průměr">Ø</th>
                                    <th className="px-1 py-2 text-center text-[10px] w-10" title="Nejlepší">Max</th>
                                    <th className="px-1 py-2 text-center text-[10px] w-8 text-red-600" title="Streak">🔥</th>
                                </>
                            )}
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {displayUsers.map((user, index) => {
                            const stats = getStats(user)!;
                            const avgPercent = Math.round(calculateRawAverage(stats));
                            const bestStreak = stats.bestStreak || 0;

                            return (
                                <tr key={index} className="hover:bg-gray-50 transition-colors">
                                    <td className={`${variant === 'compact' ? 'px-3 py-2' : 'px-6 py-4'} text-center`}>
