                                            {index + 1}
                                        </div>
                                    </td>
                                    <td className={`${variant === 'compact' ? 'px-3 py-2' : 'px-6 py-4'} font-medium text-gray-900 truncate max-w-[100px] sm:max-w-none`}>
                                        {user.displayName}
                                    </td>

                                    {/* Plná verze tabulky */}
                                    {variant === 'full' && (
                                        <>
                                            <td className={`px-6 py-4 text-center text-gray-600 font-medium ${sortType === 'GRIND' ? 'bg-blue-50/50 text-blue-800 font-bold' : ''}`}>
                                                {stats.testsTaken}x
                                            </td>
                                            <td className={`px-6 py-4 text-center font-medium ${sortType === 'AVERAGE' ? 'bg-blue-50/50 text-blue-800 font-bold' : 'text-gray-600'}`}>
                                                {avgPercent}%
                                            </td>
                                            <td className={`px-6 py-4 text-center text-lg ${sortType === 'SCORE' ? 'bg-blue-50/50 text-blue-800 font-bold' : 'text-gray-800 font-bold'}`}>
                                                {Math.round(stats.bestScorePercent)}%
                                            </td>
                                            <td className={`px-6 py-4 text-center text-lg ${sortType === 'STREAK' ? 'bg-red-50/50 text-red-700 font-black' : 'text-red-600 font-black'}`}>
                                                {bestStreak}
                                            </td>
                                        </>
                                    )}

                                    {/* Kompaktní verze widgetu */}
                                    {variant === 'compact' && (
                                        <>
                                            <td className="px-1 py-2 text-center text-xs text-gray-500">
                                                {stats.testsTaken}
                                            </td>
                                            <td className="px-1 py-2 text-center text-xs font-medium text-blue-600">
                                                {avgPercent}%
                                            </td>
                                            <td className="px-1 py-2 text-center text-sm font-bold text-gray-800">
                                                {Math.round(stats.bestScorePercent)}%
                                            </td>
                                            <td className="px-1 py-2 text-center text-sm font-black text-red-600">
                                                {bestStreak}
                                            </td>
                                        </>
                                    )}
                                </tr>
                            );
                        })}
                    </tbody>
                </table>
            </div>
            {variant === 'compact' && sortedUsers.length > 5 && (
                <div 
                    onClick={onBack} 
                    className="bg-gray-50 p-2 text-center text-xs text-gray-500 hover:text-blue-600 hover:bg-gray-100 cursor-pointer border-t border-gray-100 transition-colors"
                >
                    Zobrazit všech {sortedUsers.length} studentů...
                </div>
            )}
        </div>
      )}
    </div>
  );
};

