import React, { useEffect, useState } from 'react';
import { Subject, LeaderboardUser } from '../types';
import { db } from '../firebaseConfig';
import { collection, getDocs } from 'firebase/firestore';

interface Props {
  subject: Subject;
  onBack?: () => void;
  variant?: 'full' | 'compact'; // 'full' = celá stránka, 'compact' = widget do menu
}

type SortType = 'SCORE' | 'GRIND' | 'STREAK' | 'AVERAGE';

export const Leaderboard: React.FC<Props> = ({ subject, onBack, variant = 'full' }) => {
  const [users, setUsers] = useState<LeaderboardUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [sortType, setSortType] = useState<SortType>('SCORE');

  useEffect(() => {
    const fetchUsers = async () => {
      try {
        if (!db) return;
        const querySnapshot = await getDocs(collection(db, "users"));
        const loadedUsers: LeaderboardUser[] = [];

        querySnapshot.forEach((doc) => {
          const data = doc.data();
          if (subject === 'SPS' && data.statsSPS) {
            loadedUsers.push({ displayName: data.displayName || 'Neznámý', statsSPS: data.statsSPS });
          } else if (subject === 'STT' && data.statsSTT) {
            loadedUsers.push({ displayName: data.displayName || 'Neznámý', statsSTT: data.statsSTT });
          }
        });

        setUsers(loadedUsers);
      } catch (error) {
        console.error("Chyba při načítání žebříčku:", error instanceof Error ? error.message : error);
      } finally {
        setLoading(false);
      }
    };

    fetchUsers();
  }, [subject]);

  const getStats = (user: LeaderboardUser) => {
    return subject === 'SPS' ? user.statsSPS : user.statsSTT;
  };

  const calculateAverageValue = (stats: any) => {
      if (!stats.totalMaxPoints || stats.totalMaxPoints === 0) return 0;
      return (stats.totalPoints / stats.totalMaxPoints) * 100;
  };

  const sortedUsers = [...users].sort((a, b) => {
    const statsA = getStats(a);
    const statsB = getStats(b);

    if (!statsA || !statsB) return 0;

    switch (sortType) {
        case 'SCORE':
            if (statsB.bestScorePercent !== statsA.bestScorePercent) {
                return statsB.bestScorePercent - statsA.bestScorePercent;
            }
            return (statsB.bestStreak || 0) - (statsA.bestStreak || 0);

        case 'GRIND':
            if (statsB.testsTaken !== statsA.testsTaken) {
                return statsB.testsTaken - statsA.testsTaken;
            }
            return statsB.bestScorePercent - statsA.bestScorePercent;

        case 'AVERAGE':
            const avgA = calculateAverageValue(statsA);
            const avgB = calculateAverageValue(statsB);
            if (avgB !== avgA) return avgB - avgA;
            return statsB.testsTaken - statsA.testsTaken;

        case 'STREAK':
            const streakA = statsA.bestStreak || 0;
            const streakB = statsB.bestStreak || 0;
            if (streakB !== streakA) return streakB - streakA;
            return statsB.bestScorePercent - statsA.bestScorePercent;

        default:
            return 0;
    }
  });

  const displayUsers = variant === 'compact' ? sortedUsers.slice(0, 5) : sortedUsers;

  const getMedalColor = (index: number) => {
    if (index === 0) return "bg-yellow-100 text-yellow-700 border-yellow-300 shadow-sm";
    if (index === 1) return "bg-gray-100 text-gray-700 border-gray-300";
    if (index === 2) return "bg-orange-100 text-orange-800 border-orange-300";
    return "bg-white text-gray-600 border-gray-100";
  };

  return (
    <div className={`${variant === 'full' ? 'max-w-6xl mx-auto p-4 min-h-screen' : 'w-full h-full flex flex-col'}`}>

      <div className={`flex items-center justify-between ${variant === 'full' ? 'mb-8' : 'mb-4'}`}>
        {variant === 'full' && onBack && (
            <button 
                onClick={onBack}
                className="flex items-center text-gray-500 hover:text-gray-900 transition-colors font-medium"
            >
                <svg className="w-5 h-5 mr-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
                Zpět
            </button>
        )}
        <h1 className={`font-bold ${variant === 'full' ? 'text-3xl' : 'text-lg'} ${subject === 'SPS' ? 'text-blue-600' : 'text-orange-600'}`}>
            {variant === 'full' ? `Žebříček ${subject}` : `Top 5 ${subject}`}
        </h1>
      </div>

      {variant === 'full' && (
        <div className="flex flex-col sm:flex-row justify-between items-center gap-4 mb-8 bg-white p-5 rounded-2xl border border-gray-100 shadow-sm">
            <div className="text-gray-400 text-sm font-bold uppercase tracking-wider">
                Seřadit podle
            </div>
            <div className="flex flex-wrap gap-2">
                <button 
                    onClick={() => setSortType('SCORE')}
                    className={`px-4 py-2 rounded-xl font-bold text-sm transition-all flex items-center gap-2 border ${sortType === 'SCORE' ? 'bg-blue-600 text-white border-blue-600 shadow-lg shadow-blue-100' : 'bg-white text-gray-500 border-gray-200 hover:bg-gray-50'}`}
                >
                    <span>🏆</span> Max %
                </button>
                <button 
                    onClick={() => setSortType('AVERAGE')}
                    className={`px-4 py-2 rounded-xl font-bold text-sm transition-all flex items-center gap-2 border ${sortType === 'AVERAGE' ? 'bg-blue-600 text-white border-blue-600 shadow-lg shadow-blue-100' : 'bg-white text-gray-500 border-gray-200 hover:bg-gray-50'}`}
                >
                    <span>📊</span> Průměr
                </button>
                <button 
                    onClick={() => setSortType('GRIND')}
                    className={`px-4 py-2 rounded-xl font-bold text-sm transition-all flex items-center gap-2 border ${sortType === 'GRIND' ? 'bg-blue-600 text-white border-blue-600 shadow-lg shadow-blue-100' : 'bg-white text-gray-500 border-gray-200 hover:bg-gray-50'}`}
                >
                    <span>💪</span> Testy
                </button>
                <button 
                    onClick={() => setSortType('STREAK')}
                    className={`px-4 py-2 rounded-xl font-bold text-sm transition-all flex items-center gap-2 border ${sortType === 'STREAK' ? 'bg-red-600 text-white border-red-600 shadow-lg shadow-red-100' : 'bg-white text-gray-500 border-gray-200 hover:bg-gray-50'}`}
                >
                    <span>🔥</span> Death
                </button>
            </div>
        </div>
      )}

      {loading ? (
        <div className="text-center py-12 text-gray-400 text-sm animate-pulse">Načítám data žebříčku...</div>
      ) : displayUsers.length === 0 ? (
        <div className="text-center py-12 bg-white rounded-2xl shadow-sm border border-gray-100 border-dashed">
            <p className="text-gray-400">Zatím žádné statistiky k zobrazení.</p>
        </div>
      ) : (
        <div className={`bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden flex-1 ${variant === 'compact' ? 'text-sm' : ''}`}>
            <div className="overflow-x-auto">
