                                    <th className={`px-6 py-5 text-center transition-colors ${sortType === 'AVERAGE' ? 'text-blue-600 bg-blue-50/30' : ''}`}>Ø Úspěšnost</th>
                                    <th className={`px-6 py-5 text-center transition-colors ${sortType === 'SCORE' ? 'text-blue-600 bg-blue-50/30' : ''}`}>Maximum</th>
                                    <th className={`px-6 py-5 text-center transition-colors ${sortType === 'STREAK' ? 'text-red-600 bg-red-50/30' : ''}`}>Sudden Death 🔥</th>
                                </>
                            )}

                            {variant === 'compact' && (
                                <>
                                    <th className="px-1 py-3 text-center text-[9px] w-10">Testy</th>
                                    <th className="px-1 py-3 text-center text-[9px] w-10">Ø</th>
                                    <th className="px-1 py-3 text-center text-[9px] w-12">Max</th>
                                    <th className="px-1 py-3 text-center text-[9px] w-10 text-red-600">🔥</th>
                                </>
                            )}
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-50">
                        {displayUsers.map((user, index) => {
                            const stats = getStats(user)!;
                            const avgPercent = Math.round(calculateAverageValue(stats));
                            const bestStreak = stats.bestStreak || 0;

                            return (
                                <tr key={index} className="group hover:bg-slate-50/50 transition-colors">
                                    <td className={`${variant === 'compact' ? 'px-3 py-3' : 'px-6 py-5'} text-center`}>
                                        <div className={`${variant === 'compact' ? 'w-6 h-6 text-[10px]' : 'w-8 h-8 text-xs'} rounded-full flex items-center justify-center mx-auto font-black border ${getMedalColor(index)}`}>
                                            {index + 1}
                                        </div>
                                    </td>
                                    <td className={`${variant === 'compact' ? 'px-3 py-3' : 'px-6 py-5'} font-bold text-gray-800 truncate max-w-[120px] sm:max-w-none`}>
                                        {user.displayName}
                                    </td>

                                    {variant === 'full' && (
                                        <>
                                            <td className={`px-6 py-5 text-center text-gray-500 font-medium ${sortType === 'GRIND' ? 'bg-blue-50/20 text-blue-700 font-bold' : ''}`}>
                                                {stats.testsTaken}×
                                            </td>
                                            <td className={`px-6 py-5 text-center font-bold ${sortType === 'AVERAGE' ? 'bg-blue-50/20 text-blue-700' : 'text-gray-500'}`}>
                                                {avgPercent}%
                                            </td>
                                            <td className={`px-6 py-5 text-center text-lg ${sortType === 'SCORE' ? 'bg-blue-50/20 text-blue-700 font-black' : 'text-gray-700 font-bold'}`}>
                                                {Math.round(stats.bestScorePercent)}%
                                            </td>
                                            <td className={`px-6 py-5 text-center text-xl ${sortType === 'STREAK' ? 'bg-red-50/20 text-red-700 font-black' : 'text-red-500 font-black'}`}>
                                                {bestStreak}
                                            </td>
                                        </>
                                    )}

                                    {variant === 'compact' && (
                                        <>
                                            <td className="px-1 py-3 text-center text-gray-400 font-medium">
                                                {stats.testsTaken}
                                            </td>
                                            <td className="px-1 py-3 text-center font-bold text-blue-600/70">
                                                {avgPercent}%
                                            </td>
                                            <td className="px-1 py-3 text-center font-black text-gray-800">
                                                {Math.round(stats.bestScorePercent)}%
                                            </td>
                                            <td className="px-1 py-3 text-center font-black text-red-500">
                                                {bestStreak}
                                            </td>
                                        </>
                                    )}
                                </tr>
                            );
                        })}
                    </tbody>
                </table>
            </div>
            {variant === 'compact' && sortedUsers.length > 5 && (
                <div 
                    onClick={onBack} 
                    className="bg-gray-50 p-3 text-center text-[11px] font-bold text-gray-400 hover:text-blue-600 hover:bg-blue-50 cursor-pointer border-t border-gray-100 transition-all uppercase tracking-widest"
                >
                    Zobrazit kompletní žebříček ({sortedUsers.length})
                </div>
            )}
        </div>
      )}
    </div>
  );
};

