            </div>
        </div>
      )}

      {subject && mode === AppMode.BROWSER && (
        <div className="max-w-4xl mx-auto p-4 md:p-8">
            <div className="flex items-center gap-4 mb-8 sticky top-0 bg-slate-50 py-4 z-20">
