                  onClick={() => setMode(AppMode.MENU)} 
                  className="p-2 text-gray-500 hover:text-blue-600 hover:bg-white rounded-full transition-all shadow-none hover:shadow-sm"
                  title="Zpět do menu"
                >
                    <svg className="w-7 h-7" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
                    </svg>
                </button>

                <div className="relative flex-1">
                    <input 
                        type="text" 
                        placeholder="Hledat otázku..." 
                        value={browserSearch}
                        onChange={(e) => setBrowserSearch(e.target.value)}
                        className="w-full pl-11 pr-4 py-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-blue-500 outline-none bg-white shadow-sm transition-all"
                    />
                    <svg className="w-5 h-5 absolute left-4 top-3.5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                    </svg>
                </div>

                <button 
                    onClick={expandedIds.size > 0 ? collapseAll : expandAllVisible}
                    className="flex items-center gap-2 px-5 py-3 bg-[#f0f7ff] text-[#2563eb] rounded-xl font-bold hover:bg-blue-100 transition-colors shadow-sm whitespace-nowrap"
                >
                    {expandedIds.size > 0 ? (
                        <>
                          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 15l7-7 7 7" /></svg>
                          Zabalit vše
                        </>
                    ) : (
                        <>
                          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
                          Rozbalit vše
                        </>
                    )}
                </button>
            </div>

            <div className="space-y-4">
                {filteredBrowserQuestions.length > 0 ? (
                    filteredBrowserQuestions.map(q => (
                        <BrowserQuestionItem 
                            key={q.id} 
                            question={q} 
                            isExpanded={expandedIds.has(q.id)} 
                            onToggle={() => toggleExpand(q.id)}
                            onReportRequest={(id) => setReportingQuestionId(id)}
                        />
                    ))
                ) : (
                    <div className="text-center py-20 bg-white rounded-2xl border border-dashed border-gray-300">
                        <p className="text-gray-400">Žádné otázky neodpovídají hledání.</p>
                    </div>
                )}
            </div>
        </div>
      )}

      {subject && mode === AppMode.BATTLE && currentUser && (
          <BattleManager 
            currentUser={currentUser} 
            subject={subject} 
            stats={statsSPS}
            onExit={() => setMode(AppMode.MENU)} 
          />
      )}

      {subject && mode === AppMode.SUDDEN_DEATH && currentUser && (
          <SuddenDeathGame 
            initialQuestions={currentQuestions}
            currentUser={currentUser}
            onExit={() => setMode(AppMode.MENU)}
          />
      )}

      {subject && (mode === AppMode.MOCK_TEST || mode === AppMode.TRAINING || mode === AppMode.MISTAKES || mode === AppMode.REVIEW) && (
          <TestRunner key={subject + mode} mode={mode} mistakeIds={mode === AppMode.MISTAKES ? currentMistakes : undefined} onComplete={handleTestComplete} onExit={() => setMode(AppMode.MENU)} onReportRequest={(id) => setReportingQuestionId(id)} initialQuestionsForMode={currentQuestions} initialQuestions={mode === AppMode.REVIEW ? lastTestQuestions : undefined} initialAnswers={mode === AppMode.REVIEW ? lastUserAnswers : undefined} subject={subject} />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { AppUser } from '../users';
import { auth } from '../firebaseConfig';
import { signInWithEmailAndPassword } from 'firebase/auth';

interface Props {
  onLogin: (user: AppUser) => void;
}

export const LoginScreen: React.FC<Props> = ({ onLogin }) => {
  const [input, setInput] = useState(''); 
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const processEmail = (userInput: string) => {
      const trimmedInput = userInput.trim();
      if (trimmedInput.includes('@')) {
          return trimmedInput;
      }
      let cleanName = trimmedInput.toLowerCase();
      cleanName = cleanName.normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/\s+/g, '');
      return `${cleanName}@maturita.app`;
  };

  const getErrorMessage = (err: any) => {
      const code = err.code;
      const message = err.message || "";

      if (code === 'auth/invalid-credential' || code === 'auth/wrong-password') {
          return "Nesprávné jméno nebo heslo.";
      } else if (code === 'auth/user-not-found' || code === 'auth/invalid-email') {
          return "Tento uživatel neexistuje.";
      } else if (code === 'auth/too-many-requests') {
          return "Příliš mnoho nezdařených pokusů. Zkuste to prosím později.";
      } else if (code === 'auth/network-request-failed') {
          return "Chyba připojení k internetu.";
      } else {
          return "Chyba přihlášení: " + message;
      }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    if (!auth) {
        setError("Chyba: Firebase není nakonfigurován.");
        setLoading(false);
        return;
    }

    const emailToUse = processEmail(input);

    try {
        const userCredential = await signInWithEmailAndPassword(auth, emailToUse, password);
        onLogin({
            uid: userCredential.user.uid,
            email: emailToUse,
            displayName: userCredential.user.displayName || input
        });

    } catch (loginErr: any) {
        setError(getErrorMessage(loginErr));
    } finally {
        setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
      <div className="bg-white p-8 rounded-2xl shadow-xl max-w-sm w-full border border-gray-100">
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mx-auto mb-4">
            <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 16l-4-4m0 0l4-4m-4 4h14m-5 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h7a3 3 0 013 3v1" />
            </svg>
          </div>
          <h1 className="text-2xl font-bold text-gray-900">
              Přihlášení
          </h1>
          <p className="text-gray-500 text-sm mt-2">Maturitní testy SPS a STT</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
                Uživatelské jméno nebo Email
            </label>
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
              autoFocus
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
                 Heslo
            </label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
            />
          </div>

          {error && (
            <div className="text-red-500 text-sm text-center bg-red-50 p-3 rounded-lg border border-red-100 animate-pulse">
              <p>{error}</p>
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            className={`w-full text-white font-bold py-3 rounded-lg transition-colors shadow-md bg-blue-600 hover:bg-blue-700 ${loading ? 'opacity-70 cursor-wait' : ''}`}
          >
            {loading ? "Ověřuji..." : "Přihlásit se"}
          </button>
        </form>
      </div>
    </div>
  );
};

