import React, { useState, useEffect } from 'react';
import { Question, AppMode, TestResult } from '../types';
import { QuestionCard } from './QuestionCard';
import { db, auth } from '../firebaseConfig';
import { doc, getDoc, setDoc } from 'firebase/firestore';

interface Props {
  mode: AppMode;
  mistakeIds?: number[]; // IDs for "Oprava chyb" mode
  onComplete: (result: TestResult) => void;
  onExit: () => void;
  onReportRequest?: (qId: number) => void;

  // The full dataset for the current subject
  initialQuestionsForMode: Question[];

  // New props for Review Mode
  initialQuestions?: Question[];
  initialAnswers?: Record<number, number>;
  subject?: 'SPS' | 'STT'; // Potřebujeme vědět předmět pro ukládání statistik
}

export const TestRunner: React.FC<Props> = ({ mode, mistakeIds, onComplete, onExit, onReportRequest, initialQuestionsForMode, initialQuestions, initialAnswers, subject }) => {
  const [currentQuestions, setCurrentQuestions] = useState<Question[]>([]);
  const [answers, setAnswers] = useState<Record<number, number>>({}); // qId -> selectedIndex
  const [timeLeft, setTimeLeft] = useState(30 * 60); // 30 mins in seconds
  const [currentIndex, setCurrentIndex] = useState(0);

  // Initialize Test
  useEffect(() => {
    let q: Question[] = [];

    if (initialQuestions && mode === AppMode.REVIEW) {
        q = initialQuestions;
        if (initialAnswers) {
            setAnswers(initialAnswers);
        }
    } else if (mode === AppMode.MOCK_TEST) {
      // Shuffle and pick 40
      const shuffled = [...initialQuestionsForMode].sort(() => 0.5 - Math.random());
      q = shuffled.slice(0, 40);
    } else if (mode === AppMode.MISTAKES && mistakeIds) {
      q = initialQuestionsForMode.filter(q => mistakeIds.includes(q.id));
    } else if (mode === AppMode.TRAINING) {
      // Random training
      q = [...initialQuestionsForMode].sort(() => 0.5 - Math.random());
    } else {
        q = [...initialQuestionsForMode];
    }
    setCurrentQuestions(q);
  }, [mode, mistakeIds, initialQuestions, initialAnswers, initialQuestionsForMode]);

  // Timer Logic (Only for Mock Test)
  useEffect(() => {
    if (mode !== AppMode.MOCK_TEST) return;

    const timer = setInterval(() => {
      setTimeLeft(prev => {
        if (prev <= 1) {
          clearInterval(timer);
          finishTest();
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
    return () => clearInterval(timer);
  }, [mode]); // eslint-disable-next-line react-hooks/exhaustive-deps

  const handleAnswer = (qId: number, idx: number, isCorrect: boolean) => {
    setAnswers(prev => ({ ...prev, [qId]: idx }));
  };

  const saveStats = async (score: number, total: number) => {
      if (mode !== AppMode.MOCK_TEST || !subject || !auth.currentUser) return;

      try {
          const userRef = doc(db, "users", auth.currentUser.uid);
          const userSnap = await getDoc(userRef);

          if (userSnap.exists()) {
              const data = userSnap.data();
              const fieldName = subject === 'SPS' ? 'statsSPS' : 'statsSTT';
              const currentStats = data[fieldName] || {
                  testsTaken: 0,
                  totalPoints: 0,
                  totalMaxPoints: 0,
                  bestScorePercent: 0
              };

              const currentPercent = (score / total) * 100;

              const newStats = {
                  testsTaken: currentStats.testsTaken + 1,
                  totalPoints: currentStats.totalPoints + score,
                  totalMaxPoints: currentStats.totalMaxPoints + total,
                  bestScorePercent: Math.max(currentStats.bestScorePercent, currentPercent)
              };

              await setDoc(userRef, { [fieldName]: newStats }, { merge: true });
          }
      } catch (e) {
          console.error("Chyba při ukládání statistik:", e instanceof Error ? e.message : e);
      }
  };

  const finishTest = async () => {
    let score = 0;
    const mistakes: number[] = [];

    currentQuestions.forEach(q => {
      const userAns = answers[q.id];
      // Uznáváme jak preferovanou správnou (correctAnswerIndex), tak uznatelnou alternativu (acceptableAnswerIndex)
      const isCorrect = userAns === q.correctAnswerIndex || (q.acceptableAnswerIndex !== undefined && userAns === q.acceptableAnswerIndex);

      if (isCorrect) {
        score++;
      } else {
        mistakes.push(q.id);
      }
    });

    const total = currentQuestions.length;
    const percentage = total === 0 ? 0 : (score / total) * 100;
    const passed = percentage >= 44;

    saveStats(score, total);

    onComplete({
      score,
      total,
      passed,
      mistakes,
      timeElapsed: (30 * 60) - timeLeft,
      userAnswers: answers,
      questionsUsed: currentQuestions
    });
  };

  if (currentQuestions.length === 0) {
    return (
        <div className="text-center p-12">
            <h2 className="text-xl font-bold text-gray-700">Žádné otázky k zobrazení.</h2>
            <p className="text-gray-500 mb-4">V tomto režimu nejsou dostupné žádné otázky.</p>
            <button onClick={onExit} className="text-blue-600 underline">Zpět do menu</button>
        </div>
    );
  }

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s < 10 ? '0' : ''}${s}`;
  };

  const currentQ = currentQuestions[currentIndex];

  return (
    <div className="max-w-4xl mx-auto w-full">
      {/* Header Bar */}
      <div className="bg-white sticky top-0 z-10 shadow-sm border-b border-gray-200 px-6 py-4 mb-6 flex justify-between items-center rounded-b-xl">
        <div className="flex items-center gap-4">
            <button onClick={onExit} className="text-gray-500 hover:text-gray-900 transition-colors">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
            </button>
            <div>
                <h2 className="font-bold text-gray-800">
                    {mode === AppMode.MOCK_TEST ? 'Test nanečisto' : 
                     mode === AppMode.TRAINING ? 'Náhodný trénink' : 
                     mode === AppMode.MISTAKES ? 'Oprava chyb' : 
                     mode === AppMode.REVIEW ? 'Kontrola testu' : 'Test'}
                </h2>
                <div className="text-sm text-gray-500">
                    Otázka {currentIndex + 1} z {currentQuestions.length}
                </div>
            </div>
        </div>

        {mode === AppMode.MOCK_TEST && (
            <div className={`font-mono text-xl font-bold ${timeLeft < 300 ? 'text-red-600' : 'text-blue-600'}`}>
                {formatTime(timeLeft)}
            </div>
        )}
      </div>

      <div className="px-4">
          <QuestionCard 
            question={currentQ}
            mode={mode}
            onAnswer={handleAnswer}
            showFeedback={mode !== AppMode.MOCK_TEST}
            userAnswer={answers[currentQ.id]}
            onReportRequest={onReportRequest}
          />
      </div>

      {/* Footer Navigation */}
      <div className="flex justify-between items-center px-6 py-8">
        <button 
            onClick={() => setCurrentIndex(p => Math.max(0, p - 1))}
            disabled={currentIndex === 0}
            className="px-6 py-2 rounded-lg bg-gray-100 text-gray-700 font-medium disabled:opacity-50 hover:bg-gray-200 transition-colors"
        >
            Předchozí
        </button>

        {mode === AppMode.TRAINING || mode === AppMode.MISTAKES ? (
             <button 
             onClick={() => {
                 if (currentIndex === currentQuestions.length - 1) {
                     finishTest();
                 } else {
                    setCurrentIndex(p => p + 1);
                 }
             }}
             className="px-6 py-2 rounded-lg bg-blue-600 text-white font-bold hover:bg-blue-700 transition-colors shadow-lg shadow-blue-200"
         >
             {currentIndex === currentQuestions.length - 1 ? 'Ukončit trénink' : 'Další otázka'}
         </button>
        ) : (
            currentIndex === currentQuestions.length - 1 ? (
                <button 
                    onClick={mode === AppMode.REVIEW ? onExit : finishTest}
                    className="px-8 py-2 rounded-lg bg-green-600 text-white font-bold hover:bg-green-700 transition-colors shadow-lg shadow-green-200"
                >
                    {mode === AppMode.REVIEW ? 'Zpět do menu' : 'Vyhodnotit test'}
                </button>
            ) : (
                <button 
                    onClick={() => setCurrentIndex(p => Math.min(currentQuestions.length - 1, p + 1))}
                    className="px-6 py-2 rounded-lg bg-blue-600 text-white font-bold hover:bg-blue-700 transition-colors shadow-lg shadow-blue-200"
                >
                    Další
                </button>
            )
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Question, AppMode } from '../types';

// Definice pro globální objekt KaTeX, který načítáme v index.html
declare global {
  interface Window {
    katex: any;
  }
}

interface Props {
  question: Question;
  mode: AppMode;
  onAnswer: (questionId: number, selectedIndex: number, isCorrect: boolean) => void;
  showFeedback: boolean;
  userAnswer?: number | null;
  onReportRequest?: (qId: number) => void;
}

export const QuestionCard: React.FC<Props> = ({
  question,
  mode,
  onAnswer,
  showFeedback,
  userAnswer,
  onReportRequest
}) => {
  const [selected, setSelected] = useState<number | null>(userAnswer ?? null);
  const [imgError, setImgError] = useState(false);
  const [currentImgSrc, setCurrentImgSrc] = useState<string | undefined>(question.imageUrl);

  useEffect(() => {
    setSelected(userAnswer ?? null);
    setImgError(false);
    setCurrentImgSrc(question.imageUrl);
  }, [question, userAnswer]);

  const handleSelect = (index: number) => {
    if (showFeedback && selected !== null) return;
    if (mode === AppMode.REVIEW) return;

    setSelected(index);
    // Považujeme za správné, pokud je to preference NEBO uznatelná alternativa
    const isCorrect = index === question.correctAnswerIndex || index === question.acceptableAnswerIndex;
    onAnswer(question.id, index, isCorrect);
  };

  const handleImageError = () => {
      if (currentImgSrc && currentImgSrc.endsWith('.png')) {
          setCurrentImgSrc(currentImgSrc.replace('.png', '.jpg'));
      } else {
          setImgError(true);
      }
  };

  // --- VYLEPŠENÝ PARSER MATEMATICKÝCH VZORCŮ S KATEX ---
  const renderMathText = (text: string) => {
    if (!text) return text;

    // 1. PRIORITA: HTML (např. pro červený text v STT otázce 273)
    if (text.includes('<') && text.includes('>')) {
        return <span dangerouslySetInnerHTML={{ __html: text }} />;
    }

    // 2. PRIORITA: KaTeX (Matematika)
    const useKatex = text.includes('sqrt') || (text.includes('_') && text.includes('^'));

    if (useKatex && window.katex) {
        try {
            let latex = text;
            latex = latex.replace(/sqrt\((.+?)\)/g, '\\sqrt{$1}');
            latex = latex.replace(/(\d|[a-zA-Z])x([a-zA-Z]|\d)/g, '$1 \\cdot $2');
            latex = latex.replace(/_([a-zA-Z0-9]+)/g, '_{$1}');

            const html = window.katex.renderToString(latex, {
                throwOnError: false,
                displayMode: false
            });

            return <span dangerouslySetInnerHTML={{ __html: html }} />;
        } catch (e) {
            console.error("KaTeX error:", e);
        }
    }

    // 3. FALLBACK: Jednoduché náhrady
    let html = text;
    if (text.includes('_') || text.includes('^')) {
         html = html.replace(/(\d)x([A-Z])/g, '$1&times;$2');
         html = html.replace(/(\d)x(\d)/g, '$1&times;$2');
         html = html.replace(/ x /g, ' &times; ');
         html = html.replace(/([a-zA-Z0-9])_([a-zA-Z0-9]+)/g, '$1<sub>$2</sub>');
         html = html.replace(/\^([0-9]+)/g, '<sup>$1</sup>');
         return <span dangerouslySetInnerHTML={{ __html: html }} />;
    }

    return text;
  };

  const getOptionClass = (index: number) => {
    const base = "w-full p-4 text-left border rounded-lg transition-all duration-200 flex items-center gap-3 ";

    if (mode === AppMode.MOCK_TEST) {
      return base + (selected === index 
        ? "border-blue-500 bg-blue-50 text-blue-900 ring-2 ring-blue-200" 
        : "border-gray-200 hover:bg-gray-50 text-gray-700");
    }

    if (showFeedback || mode === AppMode.TRAINING || mode === AppMode.MISTAKES || mode === AppMode.REVIEW) {
        if (selected === null && mode !== AppMode.REVIEW) return base + "border-gray-200 hover:bg-gray-50 text-gray-700";

        // 1. Preferovaná správná odpověď (Zelená)
        if (index === question.correctAnswerIndex) {
            return base + "border-green-500 bg-green-50 text-green-900 ring-2 ring-green-200 font-medium";
        }
        // 2. Uznatelná alternativní odpověď (Žlutá)
        if (index === question.acceptableAnswerIndex) {
            // Pokud je vybrána uživatelem, svítí žlutě. V Review módu svítí žlutě vždy.
            if (selected === index || mode === AppMode.REVIEW) {
               return base + "border-yellow-500 bg-yellow-50 text-yellow-900 ring-2 ring-yellow-200 font-medium";
            }
        }
        // 3. Špatná vybraná odpověď (Červená)
        if (selected === index && index !== question.correctAnswerIndex && index !== question.acceptableAnswerIndex) {
            return base + "border-red-500 bg-red-50 text-red-900 ring-2 ring-red-200";
        }
        return base + "border-gray-200 opacity-60";
    }

    return base + "border-gray-200";
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 max-w-3xl mx-auto mb-6">
      <div className="flex justify-between items-start mb-4 gap-4">
        <h3 className="text-lg font-semibold text-gray-900 leading-relaxed flex-1">
          <span className="text-blue-600 mr-2">#{question.id}</span>
          {renderMathText(question.text)}
        </h3>
        {onReportRequest && (
          <button 
            onClick={() => onReportRequest(question.id)}
            className="text-gray-300 hover:text-red-400 p-1 transition-colors group"
            title="Nahlásit chybu v otázce"
          >
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 21v-4m0 0V5a2 2 0 012-2h6.5l1 1H21l-3 6 3 6h-8.5l-1-1H5a2 2 0 00-2 2zm9-13.5V9" /></svg>
          </button>
        )}
      </div>

      {question.imageUrl && !imgError && currentImgSrc && (
        <div className="mb-6 rounded-lg overflow-hidden border border-gray-200 bg-gray-50 min-h-[200px] flex items-center justify-center relative">
          <img 
            src={currentImgSrc} 
            alt="Ilustrace k otázce" 
            className="w-full h-auto max-h-80 object-contain mx-auto"
            onError={handleImageError}
            loading="lazy"
          />
        </div>
      )}

      {question.imageUrl && imgError && (
          <div className="mb-6 p-4 text-center text-sm text-red-400 italic bg-red-50 rounded-lg border border-red-100">
             Obrázek se nepodařilo načíst: {question.imageUrl}
          </div>
      )}

      <div className="space-y-3">
        {question.options.map((opt, idx) => (
          <button
            key={idx}
            onClick={() => handleSelect(idx)}
            disabled={((mode === AppMode.TRAINING || mode === AppMode.MISTAKES) && selected !== null) || mode === AppMode.REVIEW}
            className={getOptionClass(idx)}
          >
            <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center flex-shrink-0 
                ${selected === idx ? 'border-current' : 'border-gray-300'}`}>
                {selected === idx && <div className="w-2.5 h-2.5 rounded-full bg-current" />}
            </div>
            <span className="flex-1">{renderMathText(opt)}</span>
          </button>
        ))}
      </div>

      {/* Speciální vysvětlení pro otázku 224 */}
      {question.id === 224 && (showFeedback || mode === AppMode.REVIEW || (selected !== null && mode !== AppMode.MOCK_TEST)) && (
        <div className="mt-4 p-3 bg-blue-50 rounded-lg border border-blue-100">
          <p className="text-[11px] text-blue-700 italic">
            Poznámka: Pokud vyberete odpověď C, je také uznána jako správná. Odpověď A je však technicky přesnější preference.
          </p>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Question } from '../types';

interface Props {
  question: Question;
  isExpanded: boolean;
  onToggle: () => void;
  onReportRequest?: (qId: number) => void;
}

export const BrowserQuestionItem: React.FC<Props> = ({ question, isExpanded, onToggle, onReportRequest }) => {
  const [imgError, setImgError] = useState(false);
  const [currentImgSrc, setCurrentImgSrc] = useState<string | undefined>(question.imageUrl);

  useEffect(() => {
      if (isExpanded) {
          setImgError(false);
          setCurrentImgSrc(question.imageUrl);
      }
  }, [isExpanded, question.imageUrl]);

  const handleImageError = () => {
    if (currentImgSrc && currentImgSrc.endsWith('.png')) {
        setCurrentImgSrc(currentImgSrc.replace('.png', '.jpg'));
    } else {
        setImgError(true);
    }
  };

  const renderText = (text: string) => {
    if (!text) return text;

    if (text.includes('<') && text.includes('>')) {
        return <span dangerouslySetInnerHTML={{ __html: text }} />;
    }

    const useKatex = text.includes('sqrt') || (text.includes('_') && text.includes('^'));
    if (useKatex && window.katex) {
        try {
            let latex = text;
            latex = latex.replace(/sqrt\((.+?)\)/g, '\\sqrt{$1}');
            latex = latex.replace(/(\d|[a-zA-Z])x([a-zA-Z]|\d)/g, '$1 \\cdot $2');
            latex = latex.replace(/_([a-zA-Z0-9]+)/g, '_{$1}');

            const html = window.katex.renderToString(latex, {
                throwOnError: false,
                displayMode: false
            });
            return <span dangerouslySetInnerHTML={{ __html: html }} />;
        } catch (e) {
            console.error("KaTeX error:", e);
        }
    }

    let html = text;
    if (text.includes('_') || text.includes('^')) {
         html = html.replace(/(\d)x([A-Z])/g, '$1&times;$2');
         html = html.replace(/(\d)x(\d)/g, '$1&times;$2');
         html = html.replace(/ x /g, ' &times; ');
         html = html.replace(/([a-zA-Z0-9])_([a-zA-Z0-9]+)/g, '$1<sub>$2</sub>');
         html = html.replace(/\^([0-9]+)/g, '<sup>$1</sup>');
         return <span dangerouslySetInnerHTML={{ __html: html }} />;
    }

    return text;
  };

  const getOptionClass = (idx: number) => {
    const isCorrect = idx === question.correctAnswerIndex;
    const isAcceptable = idx === question.acceptableAnswerIndex;

    if (isCorrect) {
      return 'bg-green-50 border-green-500 text-green-900 font-semibold';
    }
    if (isAcceptable) {
      return 'bg-yellow-50 border-yellow-500 text-yellow-900 font-semibold';
    }
    return 'bg-white border-gray-200 text-gray-500';
  };

  const getIconClass = (idx: number) => {
    const isCorrect = idx === question.correctAnswerIndex;
    const isAcceptable = idx === question.acceptableAnswerIndex;

    if (isCorrect) {
      return 'border-green-600 bg-green-600 text-white';
    }
    if (isAcceptable) {
      return 'border-yellow-600 bg-yellow-600 text-white';
    }
    return 'border-gray-300';
  };

  return (
    <div 
        className={`bg-white p-5 rounded-xl shadow-sm border transition-all ${isExpanded ? 'border-blue-400 ring-2 ring-blue-100' : 'border-gray-100 hover:border-blue-200 hover:shadow-md'}`}
    >
        <div className="flex justify-between items-start gap-4">
            <div className="flex-1 cursor-pointer" onClick={onToggle}>
                <span className="font-bold text-blue-600 text-sm block mb-1">Otázka #{question.id}</span>
                <p className="text-gray-800 font-medium text-lg leading-snug">{renderText(question.text)}</p>
            </div>
            <div className="flex items-center gap-3 mt-1">
                {onReportRequest && (
                  <button 
                    onClick={(e) => {
                      e.stopPropagation();
                      onReportRequest(question.id);
                    }}
                    className="text-gray-300 hover:text-red-400 transition-colors p-1"
                    title="Nahlásit chybu"
                  >
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 21v-4m0 0V5a2 2 0 012-2h6.5l1 1H21l-3 6 3 6h-8.5l-1-1H5a2 2 0 00-2 2zm9-13.5V9" /></svg>
                  </button>
                )}
                <div onClick={onToggle} className="text-gray-400 cursor-pointer">
                    {isExpanded ? (
                        <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 15l7-7 7 7" /></svg>
                    ) : (
                        <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
                    )}
                </div>
            </div>
        </div>

        {isExpanded && (
            <div className="mt-6 pt-6 border-t border-gray-100 animate-in fade-in slide-in-from-top-2 duration-200">
                {question.imageUrl && !imgError && currentImgSrc && (
                    <div className="mb-6 bg-gray-50 rounded-lg p-2 border border-gray-200 min-h-[200px] flex items-center justify-center">
                        <img 
                            src={currentImgSrc} 
                            alt="Obrázek k otázce" 
                            className="max-h-80 w-full object-contain mx-auto"
                            onError={handleImageError}
                            loading="lazy"
                        />
                    </div>
                )}

                {question.imageUrl && imgError && (
                    <div className="mb-6 p-4 text-center text-sm text-gray-400 italic bg-gray-50 rounded-lg border border-gray-100">
                        Obrázek se nepodařilo načíst
                    </div>
                )}

                <div className="space-y-2">
                    {question.options.map((opt, idx) => {
                        const isCorrect = idx === question.correctAnswerIndex;
                        const isAcceptable = idx === question.acceptableAnswerIndex;
                        return (
                            <div 
                                key={idx} 
                                className={`p-4 rounded-lg text-base border flex items-center gap-3 ${getOptionClass(idx)}`}
                            >
                                <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center flex-shrink-0 ${getIconClass(idx)}`}>
                                    {(isCorrect || isAcceptable) && <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>}
                                </div>
                                <span className="flex-1">{renderText(opt)}</span>
                            </div>
                        )
                    })}
                </div>

                {/* Speciální vysvětlení pro otázku 224 i v prohlížeči */}
                {question.id === 224 && (
                    <div className="mt-4 p-3 bg-blue-50 rounded-lg border border-blue-100">
                        <p className="text-[11px] text-blue-700 italic">
                            Poznámka: Pokud vyberete odpověď C, je také uznána jako správná. Odpověď A je však technicky přesnější preference.
                        </p>
                    </div>
                )}
            </div>
        )}
    </div>
  );
};

import { Question } from './types';
