         html = html.replace(/([a-zA-Z0-9])_([a-zA-Z0-9]+)/g, '$1<sub>$2</sub>');
         html = html.replace(/\^([0-9]+)/g, '<sup>$1</sup>');
         return <span dangerouslySetInnerHTML={{ __html: html }} />;
    }

    return text;
  };

  const getOptionClass = (idx: number) => {
    const isCorrect = idx === question.correctAnswerIndex;
    const isAcceptable = idx === question.acceptableAnswerIndex;

    if (isCorrect) {
      return 'bg-green-50 border-green-500 text-green-900 font-semibold';
    }
    if (isAcceptable) {
      return 'bg-yellow-50 border-yellow-500 text-yellow-900 font-semibold';
    }
    return 'bg-white border-gray-200 text-gray-500';
  };

  const getIconClass = (idx: number) => {
    const isCorrect = idx === question.correctAnswerIndex;
    const isAcceptable = idx === question.acceptableAnswerIndex;

    if (isCorrect) {
      return 'border-green-600 bg-green-600 text-white';
    }
    if (isAcceptable) {
      return 'border-yellow-600 bg-yellow-600 text-white';
    }
    return 'border-gray-300';
  };

  return (
    <div 
        className={`bg-white p-5 rounded-xl shadow-sm border transition-all ${isExpanded ? 'border-blue-400 ring-2 ring-blue-100' : 'border-gray-100 hover:border-blue-200 hover:shadow-md'}`}
    >
        <div className="flex justify-between items-start gap-4">
            <div className="flex-1 cursor-pointer" onClick={onToggle}>
                <span className="font-bold text-blue-600 text-sm block mb-1">Otázka #{question.id}</span>
                <p className="text-gray-800 font-medium text-lg leading-snug">{renderText(question.text)}</p>
            </div>
            <div className="flex items-center gap-3 mt-1">
                {onReportRequest && (
                  <button 
                    onClick={(e) => {
                      e.stopPropagation();
                      onReportRequest(question.id);
                    }}
                    className="text-gray-300 hover:text-red-400 transition-colors p-1"
                    title="Nahlásit chybu"
                  >
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 21v-4m0 0V5a2 2 0 012-2h6.5l1 1H21l-3 6 3 6h-8.5l-1-1H5a2 2 0 00-2 2zm9-13.5V9" /></svg>
                  </button>
                )}
                <div onClick={onToggle} className="text-gray-400 cursor-pointer">
                    {isExpanded ? (
                        <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 15l7-7 7 7" /></svg>
                    ) : (
                        <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
                    )}
                </div>
            </div>
        </div>

        {isExpanded && (
            <div className="mt-6 pt-6 border-t border-gray-100 animate-in fade-in slide-in-from-top-2 duration-200">
                {question.imageUrl && !imgError && currentImgSrc && (
                    <div className="mb-6 bg-gray-50 rounded-lg p-2 border border-gray-200 min-h-[200px] flex items-center justify-center">
                        <img 
                            src={currentImgSrc} 
                            alt="Obrázek k otázce" 
                            className="max-h-80 w-full object-contain mx-auto"
                            onError={handleImageError}
                            loading="lazy"
                        />
                    </div>
                )}

                {question.imageUrl && imgError && (
                    <div className="mb-6 p-4 text-center text-sm text-gray-400 italic bg-gray-50 rounded-lg border border-gray-100">
                        Obrázek se nepodařilo načíst
                    </div>
                )}

                <div className="space-y-2">
                    {question.options.map((opt, idx) => {
                        const isCorrect = idx === question.correctAnswerIndex;
                        const isAcceptable = idx === question.acceptableAnswerIndex;
                        return (
                            <div 
                                key={idx} 
                                className={`p-4 rounded-lg text-base border flex items-center gap-3 ${getOptionClass(idx)}`}
                            >
                                <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center flex-shrink-0 ${getIconClass(idx)}`}>
                                    {(isCorrect || isAcceptable) && <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>}
                                </div>
                                <span className="flex-1">{renderText(opt)}</span>
                            </div>
                        )
                    })}
                </div>

                {/* Speciální vysvětlení pro otázky s více správnými odpověďmi i v prohlížeči */}
                {((question.id === 224) || (question.id === 422)) && (
                    <div className="mt-4 p-3 bg-blue-50 rounded-lg border border-blue-100">
                        <p className="text-[11px] text-blue-700 italic">
                            {question.id === 224 && "Poznámka: Pokud vyberete odpověď C, je také uznána jako správná. Odpověď A je však technicky přesnější preference."}
                            {question.id === 422 && "Poznámka: Odpovědi B i D jsou v tomto testu identické a obě jsou uznávány jako správné."}
                        </p>
                    </div>
                )}
            </div>
        )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { Subject, LeaderboardUser } from '../types';
import { db } from '../firebaseConfig';
import { collection, getDocs } from 'firebase/firestore';

interface Props {
  subject: Subject;
  onBack?: () => void;
  variant?: 'full' | 'compact'; // 'full' = celá stránka, 'compact' = widget do menu
}

type SortType = 'SCORE' | 'GRIND' | 'STREAK';

export const Leaderboard: React.FC<Props> = ({ subject, onBack, variant = 'full' }) => {
  const [users, setUsers] = useState<LeaderboardUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [sortType, setSortType] = useState<SortType>('SCORE');

  useEffect(() => {
    const fetchUsers = async () => {
      try {
        if (!db) return;
        const querySnapshot = await getDocs(collection(db, "users"));
        const loadedUsers: LeaderboardUser[] = [];

        querySnapshot.forEach((doc) => {
          const data = doc.data();
          if (subject === 'SPS' && data.statsSPS) {
            loadedUsers.push({ displayName: data.displayName || 'Neznámý', statsSPS: data.statsSPS });
          } else if (subject === 'STT' && data.statsSTT) {
            loadedUsers.push({ displayName: data.displayName || 'Neznámý', statsSTT: data.statsSTT });
          }
        });

        setUsers(loadedUsers);
      } catch (error) {
        console.error("Chyba při načítání žebříčku:", error instanceof Error ? error.message : error);
      } finally {
        setLoading(false);
      }
    };

    fetchUsers();
  }, [subject]);

  const getStats = (user: LeaderboardUser) => {
    return subject === 'SPS' ? user.statsSPS : user.statsSTT;
  };

  const sortedUsers = [...users].sort((a, b) => {
    const statsA = getStats(a);
    const statsB = getStats(b);

    if (!statsA || !statsB) return 0;

    // ŘAZENÍ OD NEJLEPŠÍHO (Sestupně)
    if (sortType === 'SCORE') {
      // 1. Primární: Nejlepší skóre v % (Max)
      if (statsB.bestScorePercent !== statsA.bestScorePercent) {
        return statsB.bestScorePercent - statsA.bestScorePercent;
      }
      // 2. Sekundární (tie-breaker): Počet testů (čím víc, tím lépe u stejného %)
      if (statsB.testsTaken !== statsA.testsTaken) {
        return statsB.testsTaken - statsA.testsTaken;
      }
      // 3. Terciární: Best Streak
      return (statsB.bestStreak || 0) - (statsA.bestStreak || 0);
    } 

    else if (sortType === 'GRIND') {
      // Primárně podle počtu testů
      if (statsB.testsTaken !== statsA.testsTaken) {
        return statsB.testsTaken - statsA.testsTaken;
      }
      return statsB.bestScorePercent - statsA.bestScorePercent;
    } 

    else {
      // Primárně podle streaku (Sudden Death)
      const streakA = statsA.bestStreak || 0;
      const streakB = statsB.bestStreak || 0;
      if (streakB !== streakA) return streakB - streakA;
      return statsB.bestScorePercent - statsA.bestScorePercent;
    }
  });

  // V kompaktním režimu ukážeme jen TOP 5
  const displayUsers = variant === 'compact' ? sortedUsers.slice(0, 5) : sortedUsers;

  const getMedalColor = (index: number) => {
    if (index === 0) return "bg-yellow-100 text-yellow-700 border-yellow-300 shadow-sm ring-2 ring-yellow-50";
    if (index === 1) return "bg-slate-100 text-slate-700 border-slate-300";
    if (index === 2) return "bg-amber-100 text-amber-800 border-amber-300";
    return "bg-white text-gray-600 border-gray-100";
  };

  const calculateAverage = (totalPoints: number, totalMaxPoints: number) => {
      if (!totalMaxPoints || totalMaxPoints === 0) return 0;
      return Math.round((totalPoints / totalMaxPoints) * 100);
  };

  return (
    <div className={`${variant === 'full' ? 'max-w-6xl mx-auto p-4 min-h-screen' : 'w-full h-full flex flex-col'}`}>

      {/* Header */}
      <div className={`flex items-center justify-between ${variant === 'full' ? 'mb-8' : 'mb-4'}`}>
        {variant === 'full' && onBack && (
            <button 
                onClick={onBack}
                className="flex items-center text-gray-500 hover:text-gray-900 transition-colors group"
            >
                <svg className="w-6 h-6 mr-1 transition-transform group-hover:-translate-x-1" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
                Zpět
            </button>
        )}
        <h1 className={`font-bold ${variant === 'full' ? 'text-2xl' : 'text-lg'} ${subject === 'SPS' ? 'text-blue-600' : 'text-orange-600'}`}>
            {variant === 'full' ? `Žebříček ${subject}` : `Top ${subject}`}
        </h1>
      </div>

      {/* Přepínač řazení pouze pro plnou verzi */}
      {variant === 'full' && (
        <div className="flex flex-col sm:flex-row justify-between items-center gap-4 mb-6 bg-white p-4 rounded-xl border border-gray-100 shadow-sm">
            <div className="text-gray-500 text-sm font-semibold uppercase tracking-wider">
                Seřadit studenty dle:
            </div>
            <div className="flex flex-wrap gap-2 bg-gray-100 p-1 rounded-lg">
                <button 
                    onClick={() => setSortType('SCORE')}
                    className={`px-4 py-2 rounded-md font-bold text-sm transition-all flex items-center gap-2 ${sortType === 'SCORE' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    <span>🎯</span> Nejlepší Max %
                </button>
                <button 
                    onClick={() => setSortType('GRIND')}
                    className={`px-4 py-2 rounded-md font-bold text-sm transition-all flex items-center gap-2 ${sortType === 'GRIND' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    <span>💪</span> Počet testů
                </button>
                <button 
                    onClick={() => setSortType('STREAK')}
                    className={`px-4 py-2 rounded-md font-bold text-sm transition-all flex items-center gap-2 ${sortType === 'STREAK' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    <span>🔥</span> Sudden Death
                </button>
            </div>
        </div>
      )}

      {loading ? (
        <div className="text-center py-8 text-gray-400 text-sm animate-pulse">Načítám data studentů...</div>
      ) : displayUsers.length === 0 ? (
        <div className="text-center py-8 bg-white rounded-xl shadow-sm border border-gray-200 border-dashed">
            <p className="text-gray-400 text-sm">Zatím žádné statistiky pro tento předmět.</p>
        </div>
      ) : (
        <div className={`bg-white rounded-xl shadow-md border border-gray-200 overflow-hidden flex-1 ${variant === 'compact' ? 'text-sm' : ''}`}>
            <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                    <thead>
                        <tr className="bg-gray-50 text-gray-500 text-[10px] sm:text-xs uppercase tracking-wider border-b border-gray-200">
                            <th className={`${variant === 'compact' ? 'px-2 py-2' : 'px-6 py-4'} text-center w-8`}>#</th>
                            <th className={`${variant === 'compact' ? 'px-2 py-2' : 'px-6 py-4'}`}>Student</th>

                            {variant === 'full' && (
                                <>
                                    <th className="px-6 py-4 text-center whitespace-nowrap">Testy</th>
                                    <th className="px-6 py-4 text-center whitespace-nowrap">Průměr Ø</th>
                                    <th className={`px-6 py-4 text-center whitespace-nowrap ${sortType === 'SCORE' ? 'text-blue-600 font-black bg-blue-50/30' : ''}`}>Nejlepší Max</th>
                                    <th className={`px-6 py-4 text-center whitespace-nowrap ${sortType === 'STREAK' ? 'text-red-600 font-black bg-red-50/30' : 'text-red-400'}`}>Streak 🔥</th>
                                </>
                            )}

                            {variant === 'compact' && (
                                <>
                                    <th className="px-1 py-2 text-center text-[10px] w-8">T</th>
                                    <th className="px-1 py-2 text-center text-[10px] w-8">Ø</th>
                                    <th className="px-1 py-2 text-center text-[10px] w-10 text-blue-600 font-bold">Max</th>
                                    <th className="px-1 py-2 text-center text-[10px] w-8 text-red-500 font-bold">🔥</th>
                                </>
                            )}
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {displayUsers.map((user, index) => {
                            const stats = getStats(user)!;
                            const avgPercent = calculateAverage(stats.totalPoints, stats.totalMaxPoints);
                            const bestStreak = stats.bestStreak || 0;
                            const bestScore = Math.round(stats.bestScorePercent);

                            return (
                                <tr key={index} className={`transition-colors ${index < 3 && variant === 'compact' ? 'bg-gray-50/30' : 'hover:bg-gray-50'}`}>
                                    <td className={`${variant === 'compact' ? 'px-2 py-2' : 'px-6 py-4'} text-center`}>
                                        <div className={`${variant === 'compact' ? 'w-5 h-5 text-[10px]' : 'w-8 h-8 text-sm'} rounded-full flex items-center justify-center mx-auto font-black border ${getMedalColor(index)}`}>
                                            {index + 1}
                                        </div>
                                    </td>
                                    <td className={`${variant === 'compact' ? 'px-2 py-2' : 'px-6 py-4'} font-semibold text-gray-900 truncate max-w-[90px] sm:max-w-none`}>
                                        {user.displayName}
                                    </td>

                                    {/* Plná verze tabulky */}
                                    {variant === 'full' && (
                                        <>
                                            <td className="px-6 py-4 text-center text-gray-500">
                                                {stats.testsTaken}x
                                            </td>
                                            <td className="px-6 py-4 text-center font-medium text-slate-400">
                                                {avgPercent}%
                                            </td>
                                            <td className={`px-6 py-4 text-center font-black text-xl ${bestScore >= 44 ? 'text-green-600' : 'text-red-500'} ${sortType === 'SCORE' ? 'bg-blue-50/20' : ''}`}>
                                                {bestScore}%
                                            </td>
                                            <td className={`px-6 py-4 text-center font-black text-lg ${bestStreak > 0 ? 'text-red-600' : 'text-gray-300'} ${sortType === 'STREAK' ? 'bg-red-50/20' : ''}`}>
                                                {bestStreak}
                                            </td>
                                        </>
                                    )}

                                    {/* Kompaktní verze widgetu */}
                                    {variant === 'compact' && (
                                        <>
                                            <td className="px-1 py-2 text-center text-[10px] text-gray-400">
                                                {stats.testsTaken}
                                            </td>
                                            <td className="px-1 py-2 text-center text-[10px] text-slate-300">
                                                {avgPercent}
                                            </td>
                                            <td className={`px-1 py-2 text-center text-xs font-black ${bestScore >= 44 ? 'text-green-600' : 'text-red-500'}`}>
                                                {bestScore}%
                                            </td>
                                            <td className={`px-1 py-2 text-center text-xs font-black ${bestStreak > 0 ? 'text-red-600' : 'text-gray-300'}`}>
                                                {bestStreak}
                                            </td>
                                        </>
                                    )}
                                </tr>
                            );
                        })}
                    </tbody>
                </table>
            </div>
            {variant === 'compact' && sortedUsers.length > 5 && (
                <div 
                    onClick={onBack} 
                    className="bg-gray-50 p-2 text-center text-[10px] uppercase font-bold text-gray-400 hover:text-blue-600 hover:bg-white cursor-pointer border-t border-gray-100 transition-all"
                >
                    Zobrazit kompletní pořadí ({sortedUsers.length} studentů)
                </div>
            )}
        </div>
      )}
    </div>
  );
};

