// Fix: Export App as default to satisfy index.tsx import
const App: React.FC = () => {
  const [user, setUser] = useState<AppUser | null>(null);
  const [userStats, setUserStats] = useState<any>(null);
  const [mode, setMode] = useState<AppMode>(AppMode.MENU);
  const [subject, setSubject] = useState<Subject>('SPS');

  const [mistakesSPS, setMistakesSPS] = useState<number[]>([]);
  const [mistakesSTT, setMistakesSTT] = useState<number[]>([]);

  const [showSPSInfo, setShowSPSInfo] = useState(false);
  const [showSTTInfo, setShowSTTInfo] = useState(false);
  const [showApiKeyModal, setShowApiKeyModal] = useState(false);
  const [showReportModal, setShowReportModal] = useState<{show: boolean, qId: number}>({show: false, qId: 0});

  const [browserSearch, setBrowserSearch] = useState("");
  const [expandedIds, setExpandedIds] = useState<Set<number>>(new Set());

  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged(async (firebaseUser) => {
      if (firebaseUser) {
        setUser({
          uid: firebaseUser.uid,
          email: firebaseUser.email || '',
          displayName: firebaseUser.displayName || ''
        });

        const userRef = doc(db, "users", firebaseUser.uid);
        const snap = await getDoc(userRef);
        if (snap.exists()) {
            const data = snap.data();
            setUserStats(data);
            setMistakesSPS(data.mistakesSPS || []);
            setMistakesSTT(data.mistakesSTT || []);
        }
      } else {
        setUser(null);
        setUserStats(null);
      }
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    const hideSPS = localStorage.getItem('hideSPSInfo');
    const hideSTT = localStorage.getItem('hideSTTInfo');
    if (!hideSPS) setShowSPSInfo(true);
    if (!hideSTT) setShowSTTInfo(true);
  }, []);

  const handleLogin = (u: AppUser) => {
      // Handled by onAuthStateChanged
  };

  const handleLogout = () => {
      signOut(auth);
      setMode(AppMode.MENU);
  };

  const saveMistakesToDb = async (newSPS: number[], newSTT: number[]) => {
      if (user) {
          try {
             await setDoc(doc(db, "users", user.uid), {
                 mistakesSPS: newSPS,
                 mistakesSTT: newSTT
             }, { merge: true });
          } catch (e) {
              console.error("Failed to save mistakes", e);
          }
      }
  };

  const handleTestComplete = (result: TestResult) => {
    if (mode === AppMode.MOCK_TEST || mode === AppMode.TRAINING) {
        if (subject === 'SPS') {
            const newMistakes = Array.from(new Set([...mistakesSPS, ...result.mistakes]));
            setMistakesSPS(newMistakes);
            saveMistakesToDb(newMistakes, mistakesSTT);
        } else {
            const newMistakes = Array.from(new Set([...mistakesSTT, ...result.mistakes]));
            setMistakesSTT(newMistakes);
            saveMistakesToDb(mistakesSPS, newMistakes);
        }
    } else if (mode === AppMode.MISTAKES) {
        const answeredCorrectly = Object.keys(result.userAnswers).map(Number).filter(qId => !result.mistakes.includes(qId));

        if (subject === 'SPS') {
            const newMistakes = mistakesSPS.filter(id => !answeredCorrectly.includes(id));
            setMistakesSPS(newMistakes);
            saveMistakesToDb(newMistakes, mistakesSTT);
        } else {
            const newMistakes = mistakesSTT.filter(id => !answeredCorrectly.includes(id));
            setMistakesSTT(newMistakes);
            saveMistakesToDb(mistakesSPS, newMistakes);
        }
    }
    setMode(AppMode.MENU);
  };

  const getMenuButtonClass = (extra: string) => {
      return `w-full p-6 rounded-2xl shadow-sm border border-gray-100 transition-all active:scale-[0.98] flex items-center gap-4 text-left ` + extra;
  };

  const currentQuestions = subject === 'SPS' ? QUESTIONS_SPS : QUESTIONS_STT;
  const currentMistakes = subject === 'SPS' ? mistakesSPS : mistakesSTT;

  const getFilteredBrowserQuestions = () => {
      if (!browserSearch) return currentQuestions;
      const term = browserSearch.toLowerCase();
      return currentQuestions.filter(q => 
          q.text.toLowerCase().includes(term) || 
          q.id.toString().includes(term)
      );
  };

  if (!user) {
    return <LoginScreen onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-screen bg-[#f8fafc] text-gray-900 font-sans">
        {showApiKeyModal && <ApiKeyModal onClose={() => setShowApiKeyModal(false)} />}
        {showReportModal.show && (
            <ReportModal 
                questionId={showReportModal.qId} 
                subject={subject} 
                userName={user.displayName} 
                onClose={() => setShowReportModal({show: false, qId: 0})} 
            />
        )}
        {showSPSInfo && subject === 'SPS' && <SPSInfoModal onConfirm={() => setShowSPSInfo(false)} />}
        {showSTTInfo && subject === 'STT' && <STTInfoModal onConfirm={() => setShowSTTInfo(false)} />}

        {mode === AppMode.MENU && (
            <div className="max-w-md mx-auto p-6 pb-24">
                <header className="flex justify-between items-center mb-8 pt-4">
                    <div>
                        <h1 className="text-2xl font-black text-gray-900 tracking-tight">Maturita App</h1>
                        <p className="text-gray-500 text-sm font-medium">Vítej, {user.displayName}</p>
                    </div>
                    <div className="flex gap-2">
                        <button onClick={() => setShowApiKeyModal(true)} className="p-2 bg-white rounded-xl shadow-sm border border-gray-200 text-gray-600 hover:text-blue-600">
                             <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 7a2 2 0 012 2m4 0a6 6 0 01-7.743 5.743L11 17H9v2H7v2H4a1 1 0 01-1-1v-2.586a1 1 0 01.293-.707l5.964-5.964A6 6 0 1121 9z" /></svg>
                        </button>
                        <button onClick={handleLogout} className="p-2 bg-white rounded-xl shadow-sm border border-gray-200 text-gray-600 hover:text-red-600">
                             <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
                        </button>
                    </div>
                </header>

                <div className="bg-white p-1 rounded-2xl shadow-sm border border-gray-100 flex mb-8">
                    <button 
                        onClick={() => setSubject('SPS')}
                        className={`flex-1 py-3 rounded-xl font-bold text-sm transition-all ${subject === 'SPS' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-50'}`}
                    >
                        SPS (Stroje)
                    </button>
                    <button 
                        onClick={() => setSubject('STT')}
                        className={`flex-1 py-3 rounded-xl font-bold text-sm transition-all ${subject === 'STT' ? 'bg-orange-600 text-white shadow-md' : 'text-gray-500 hover:bg-gray-50'}`}
                    >
                        STT (Technologie)
                    </button>
                </div>

                <div className="space-y-4">
                    <button onClick={() => setMode(AppMode.MOCK_TEST)} className={getMenuButtonClass("bg-white hover:bg-blue-50 text-blue-700")}>
                        <div className="bg-blue-100 p-3 rounded-full"><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01" /></svg></div>
                        <div><div className="font-bold text-lg">Test nanečisto</div><div className="text-sm text-gray-500 font-normal">40 otázek • 30 minut</div></div>
                    </button>

                    <button onClick={() => setMode(AppMode.TRAINING)} className={getMenuButtonClass("bg-white hover:bg-green-50 text-green-700")}>
                        <div className="bg-green-100 p-3 rounded-full"><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg></div>
                        <div><div className="font-bold text-lg">Náhodný trénink</div><div className="text-sm text-gray-500 font-normal">Procvičování bez limitu</div></div>
                    </button>

                    <button onClick={() => setMode(AppMode.MISTAKES)} disabled={currentMistakes.length === 0} className={getMenuButtonClass(currentMistakes.length > 0 ? "bg-white hover:bg-orange-50 text-orange-700" : "bg-gray-100 text-gray-400 cursor-not-allowed")}>
                        <div className={`${currentMistakes.length > 0 ? 'bg-orange-100' : 'bg-gray-200'} p-3 rounded-full`}><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg></div>
                        <div><div className="font-bold text-lg">Oprava chyb</div><div className="text-sm font-normal">{currentMistakes.length} chyb v paměti</div></div>
                    </button>

                    <button onClick={() => { setMode(AppMode.BROWSER); setBrowserSearch(""); setExpandedIds(new Set()); }} className={getMenuButtonClass("bg-white hover:bg-indigo-50 text-indigo-700")}>
                        <div className="bg-indigo-100 p-3 rounded-full"><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg></div>
                        <div><div className="font-bold text-lg">Prohlížet otázky</div><div className="text-sm text-gray-500 font-normal">Databáze {currentQuestions.length} otázek</div></div>
                    </button>

                    {subject === 'SPS' && (
                        <>
                            <div className="pt-4 border-t border-gray-200">
                                <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-3">Multiplayer & Výzvy</h3>
                                <button onClick={() => setMode(AppMode.BATTLE_HUB)} className={getMenuButtonClass("bg-gradient-to-r from-violet-600 to-indigo-600 text-white shadow-lg shadow-indigo-200 border-none")}>
                                    <div className="bg-white/20 p-3 rounded-full"><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg></div>
                                    <div><div className="font-bold text-lg">1v1 Bitva</div><div className="text-sm text-white/80 font-normal">Vyzvi spolužáka</div></div>
                                </button>
                                <button onClick={() => setMode(AppMode.SUDDEN_DEATH)} className="w-full mt-4 p-6 rounded-2xl shadow-sm border border-red-100 bg-white hover:bg-red-50 text-red-700 transition-all flex items-center gap-4 text-left">
                                    <div className="bg-red-100 p-3 rounded-full"><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg></div>
                                    <div><div className="font-bold text-lg">Náhlá smrt</div><div className="text-sm font-normal">Jedna chyba a konec</div></div>
                                </button>
                            </div>
                        </>
                    )}

                    <div className="pt-4 border-t border-gray-200">
                        <button onClick={() => setMode(AppMode.LEADERBOARD)} className="w-full p-4 rounded-xl bg-yellow-50 text-yellow-800 border border-yellow-100 hover:bg-yellow-100 transition-colors font-bold flex items-center justify-center gap-2">
                            <span>🏆</span> Zobrazit žebříček
                        </button>
                    </div>

                    <div className="mt-8">
                         <Leaderboard subject={subject} variant="compact" />
                    </div>
                </div>
            </div>
        )}

        {(mode === AppMode.MOCK_TEST || mode === AppMode.TRAINING || mode === AppMode.MISTAKES) && (
            <TestRunner 
                mode={mode}
                subject={subject}
                mistakeIds={mode === AppMode.MISTAKES ? currentMistakes : undefined}
                onComplete={handleTestComplete}
                onExit={() => setMode(AppMode.MENU)}
                initialQuestionsForMode={currentQuestions}
                onReportRequest={(qId) => setShowReportModal({show: true, qId})}
            />
        )}

        {mode === AppMode.BROWSER && (
            <div className="max-w-4xl mx-auto p-4 min-h-screen">
                <div className="flex items-center gap-4 mb-6 sticky top-0 bg-[#f8fafc] z-10 py-4 border-b border-gray-200">
                    <button onClick={() => setMode(AppMode.MENU)} className="p-2 bg-white rounded-lg border border-gray-200 hover:bg-gray-50">
                        <svg className="w-6 h-6 text-gray-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
                    </button>
                    <div className="flex-1 relative">
                        <input 
                            type="text" 
                            value={browserSearch}
                            onChange={(e) => setBrowserSearch(e.target.value)}
                            placeholder="Hledat otázku (číslo nebo text)..."
                            className="w-full p-3 pl-10 rounded-xl border border-gray-200 focus:ring-2 focus:ring-blue-500 outline-none"
                        />
                        <svg className="w-5 h-5 text-gray-400 absolute left-3 top-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                    </div>
                </div>

                <div className="space-y-4 pb-20">
                    {getFilteredBrowserQuestions().slice(0, 100).map(q => (
                        <BrowserQuestionItem 
                            key={q.id} 
                            question={q} 
                            isExpanded={expandedIds.has(q.id)}
                            onToggle={() => {
                                const newSet = new Set(expandedIds);
                                if (newSet.has(q.id)) newSet.delete(q.id);
                                else newSet.add(q.id);
                                setExpandedIds(newSet);
                            }}
                            onReportRequest={(qId) => setShowReportModal({show: true, qId})}
                        />
                    ))}
                    {getFilteredBrowserQuestions().length > 100 && (
                        <p className="text-center text-gray-400 italic py-4">Zobrazeno prvních 100 výsledků...</p>
                    )}
                    {getFilteredBrowserQuestions().length === 0 && (
                         <p className="text-center text-gray-500 py-10">Žádné otázky nenalezeny.</p>
                    )}
                </div>
            </div>
        )}

        {mode === AppMode.LEADERBOARD && (
            <Leaderboard subject={subject} onBack={() => setMode(AppMode.MENU)} />
        )}

        {mode === AppMode.BATTLE_HUB && (
            <BattleManager 
                currentUser={user} 
                subject={subject} 
                stats={userStats?.statsSPS || {}} 
                onExit={() => setMode(AppMode.MENU)} 
            />
        )}

        {mode === AppMode.SUDDEN_DEATH && (
            <SuddenDeathGame 
                initialQuestions={currentQuestions} 
                currentUser={user}
                onExit={() => setMode(AppMode.MENU)} 
            />
        )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { AppUser } from './users';
import { auth, db } from './firebaseConfig';
import { onAuthStateChanged, signOut } from 'firebase/auth';
import { doc, getDoc, setDoc } from 'firebase/firestore';
import { QUESTIONS_SPS, QUESTIONS_STT } from './constants';
import { AppMode, Subject, TestResult } from './types';

// Components
import { LoginScreen } from './components/LoginScreen';
import { TestRunner } from './components/TestRunner';
import { BrowserQuestionItem } from './components/BrowserQuestionItem';
import { Leaderboard } from './components/Leaderboard';
import { BattleManager } from './components/BattleManager';
import { SuddenDeathGame } from './components/SuddenDeathGame';
import { SPSInfoModal } from './components/SPSInfoModal';
import { STTInfoModal } from './components/STTInfoModal';
import { ReportModal } from './components/ReportModal';
import { ApiKeyModal } from './components/ApiKeyModal';

const App: React.FC = () => {
  const [user, setUser] = useState<AppUser | null>(null);
  const [mode, setMode] = useState<AppMode>(AppMode.MENU);
  const [subject, setSubject] = useState<Subject>('SPS');

  // Data lists
  const currentQuestions = subject === 'SPS' ? QUESTIONS_SPS : QUESTIONS_STT;

  // Mistakes state
  const [mistakesSPS, setMistakesSPS] = useState<number[]>([]);
  const [mistakesSTT, setMistakesSTT] = useState<number[]>([]);

  const currentMistakes = subject === 'SPS' ? mistakesSPS : mistakesSTT;

  // Browser state
  const [browserSearch, setBrowserSearch] = useState("");
  const [expandedIds, setExpandedIds] = useState<Set<number>>(new Set());

  // Report modal state
  const [reportQuestionId, setReportQuestionId] = useState<number | null>(null);

  // Info modal states
  const [showSPSInfo, setShowSPSInfo] = useState(false);
  const [showSTTInfo, setShowSTTInfo] = useState(false);

  // API Key Modal
  const [showApiKeyModal, setShowApiKeyModal] = useState(false);

  // Battle stats & User Stats
  const [userStats, setUserStats] = useState<any>(null);

  // Review state
  const [lastTestResult, setLastTestResult] = useState<TestResult | null>(null);

  // Auth Effect
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
      if (firebaseUser) {
        // Fetch user data from Firestore
        const userRef = doc(db, "users", firebaseUser.uid);
        const userSnap = await getDoc(userRef);

        let userData: AppUser = {
           uid: firebaseUser.uid,
           email: firebaseUser.email || '',
           displayName: firebaseUser.displayName || ''
        };

        if (userSnap.exists()) {
           const data = userSnap.data();
           userData = { ...userData, displayName: data.displayName || userData.displayName };
           setUserStats(data);
        } else {
           // Create user doc if not exists
           await setDoc(userRef, {
             email: firebaseUser.email,
             displayName: firebaseUser.displayName,
             statsSPS: { testsTaken: 0, totalPoints: 0, totalMaxPoints: 0, bestScorePercent: 0 },
             statsSTT: { testsTaken: 0, totalPoints: 0, totalMaxPoints: 0, bestScorePercent: 0 }
           });
        }
        setUser(userData);
      } else {
        setUser(null);
        setMode(AppMode.MENU);
      }
    });
    return () => unsubscribe();
  }, []);

  // Check LocalStorage for Info Modals preference
  useEffect(() => {
    if (subject === 'SPS') {
      const hideSPS = localStorage.getItem('hideSPSInfo');
      if (!hideSPS && mode === AppMode.MOCK_TEST) setShowSPSInfo(true);
    }
    if (subject === 'STT') {
      const hideSTT = localStorage.getItem('hideSTTInfo');
      if (!hideSTT && mode === AppMode.MOCK_TEST) setShowSTTInfo(true);
    }
  }, [mode, subject]);

  const handleLogout = async () => {
    await signOut(auth);
    setUser(null);
  };

  const handleTestComplete = (result: TestResult) => {
    // Save mistakes
    const incorrectIds = result.mistakes;
    if (incorrectIds.length > 0) {
      if (subject === 'SPS') {
        setMistakesSPS(prev => Array.from(new Set([...prev, ...incorrectIds])));
      } else {
        setMistakesSTT(prev => Array.from(new Set([...prev, ...incorrectIds])));
      }
    }

    // Remove corrected mistakes if in MISTAKES mode
    if (mode === AppMode.MISTAKES) {
         const correctIds = result.questionsUsed
            .filter(q => {
                const ans = result.userAnswers[q.id];
                return ans === q.correctAnswerIndex || ans === q.acceptableAnswerIndex;
            })
            .map(q => q.id);

         if (subject === 'SPS') {
             setMistakesSPS(prev => prev.filter(id => !correctIds.includes(id)));
         } else {
             setMistakesSTT(prev => prev.filter(id => !correctIds.includes(id)));
         }
    }

    setLastTestResult(result);
    setMode(AppMode.REVIEW);
  };

  const getMenuButtonClass = (customClasses: string) => {
    return `w-full p-4 rounded-xl shadow-sm border border-gray-100 flex items-center gap-4 transition-all duration-200 text-left ${customClasses}`;
  };

  const filteredBrowserQuestions = useMemo(() => {
      if (!browserSearch) return currentQuestions;
      const lower = browserSearch.toLowerCase();
      return currentQuestions.filter(q => 
          q.text.toLowerCase().includes(lower) || 
          q.id.toString().includes(lower) ||
          q.options.some(o => o.toLowerCase().includes(lower))
      );
  }, [browserSearch, currentQuestions]);

  const handleToggleExpand = (id: number) => {
      const newSet = new Set(expandedIds);
      if (newSet.has(id)) newSet.delete(id);
      else newSet.add(id);
      setExpandedIds(newSet);
  };

  if (!user) {
    return <LoginScreen onLogin={() => {}} />;
  }

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 font-sans pb-10">

      {/* Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-30 shadow-sm">
        <div className="max-w-6xl mx-auto px-4 py-3 flex justify-between items-center">
            <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white font-bold text-xl shadow-lg shadow-blue-200">
                    M
                </div>
                <div>
                    <h1 className="font-bold text-gray-900 leading-none">Maturita App</h1>
                    <p className="text-xs text-gray-500 font-medium">SPS & STT</p>
                </div>
            </div>

            <div className="flex items-center gap-4">
                <div className="hidden sm:block text-right">
                    <p className="text-sm font-bold text-gray-900">{user.displayName}</p>
                    <p className="text-xs text-gray-500">{user.email}</p>
                </div>
                <button onClick={handleLogout} className="p-2 text-gray-400 hover:text-red-500 transition-colors" title="Odhlásit se">
                    <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
                </button>
            </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-6xl mx-auto px-4 py-6">

        {/* MENU MODE */}
        {mode === AppMode.MENU && (
            <div className="max-w-md mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">

                {/* Subject Switcher */}
                <div className="bg-white p-1.5 rounded-2xl shadow-sm border border-gray-200 flex">
                    <button 
                        onClick={() => setSubject('SPS')}
                        className={`flex-1 py-3 rounded-xl font-bold text-sm transition-all ${subject === 'SPS' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:text-gray-900 hover:bg-gray-50'}`}
                    >
                        SPS (Stroje)
                    </button>
                    <button 
                        onClick={() => setSubject('STT')}
                        className={`flex-1 py-3 rounded-xl font-bold text-sm transition-all ${subject === 'STT' ? 'bg-orange-600 text-white shadow-md' : 'text-gray-500 hover:text-gray-900 hover:bg-gray-50'}`}
                    >
                        STT (Technologie)
                    </button>
